    public ModelAndView createManualTender(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();
        String tenderPhase = request.getParameter("tenderPhase");
        String ref_no = request.getParameter("ref_no");

        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String formattedDate = myDateObj.format(myFormatObj);

        DateTimeFormatter myFormatObj1 = DateTimeFormatter.ofPattern("dd-MM-yyyy");
        String submitLastdate = myDateObj.format(myFormatObj1);
        String submitLastdate1 = submitLastdate;
        submitLastdate = submitLastdate + " 12:00:00";

        SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

        Date d1 = sdf.parse(formattedDate);
        Date d2 = sdf.parse(submitLastdate);

        long difference_In_Time
                = d2.getTime() - d1.getTime();

        if (difference_In_Time < 0) {
            String dt = submitLastdate1;  // Start date
            SimpleDateFormat sdf11 = new SimpleDateFormat("dd-MM-yyyy");
            Calendar c = Calendar.getInstance();
            c.setTime(sdf11.parse(dt));
            c.add(Calendar.DATE, 1);  // number of days to add
            dt = sdf11.format(c.getTime());
            submitLastdate1 = dt;
            submitLastdate = submitLastdate1 + " 12:00:00";
        }

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        EmployeeMaster employeeMaster = employeeMasterService.readUser(username);

        String employee_name = employeeMaster.getName();
        String ph_no = employeeMaster.getPhNo();
        String location = employeeMaster.getLocation();

        List locationMaster = locationMasterService.read();
        List plantMaster = plantMasterService.read();
        List termsCondition = termsConditionService.read();
        mv.getModelMap().put("termsCondition", termsCondition);

        mv.getModelMap().put("plantMaster", plantMaster);

        //    List list = employeeMasterService.readByDrow();
        //    request.setAttribute("list", list);
        mv.getModelMap().put("locationMaster", locationMaster);
        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.getModelMap().put("tenderPhase", tenderPhase);
        mv.getModelMap().put("ref_no", ref_no);
        mv.getModelMap().put("employee_name", employee_name);
        mv.getModelMap().put("ph_no", ph_no);
        mv.getModelMap().put("location", location);
        mv.getModelMap().put("formattedDate", formattedDate);
        mv.getModelMap().put("submitLastdate", submitLastdate);

        if (session != null) {

            String successMessage = (String) session.getAttribute("successMessage");
            if (successMessage != null) {
                mv.addObject("successMessage", successMessage);
                session.removeAttribute("successMessage");
            }

            String failureMessage = (String) session.getAttribute("failureMessage");
            if (failureMessage != null) {
                mv.addObject("failureMessage", failureMessage);
                session.removeAttribute("failureMessage");
            }
        }

        mv.setViewName("Tender/CreateManualTender");
        return mv;
    }

