    public ModelAndView approvedTechnicalBidListSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        String refNo = request.getParameter("tenderNo");
        String bidType = "2";

        List<TenderCommittee> committeeList = tenderCommitteeService.readByRefUser(refNo, username, bidType);

        if (committeeList != null && !committeeList.isEmpty()) {
            TenderCommittee tenderCommittee = committeeList.get(0); // Assuming only one per user

            if (tenderCommittee.getUserId().equals(username)) {
                TenderMaster tm = tenderMasterService.readRefNo(refNo);
                List list1 = tenderVendorService.vendorList(refNo);

                int vendor_total = list1.size();

                int id = tm.getId();
                String title = tm.getTitle();
                String announceDate = tm.getAnnounceDate();
                String submitLastdate = tm.getSubmitLastdate();
                String contactPerson = tm.getContactPerson();
                int tenderPhase = tm.getTenderPhase();

                mv.getModelMap().put("id", id);
                mv.getModelMap().put("username", username);
                mv.getModelMap().put("refNo", refNo);
                mv.getModelMap().put("title", title);
                mv.getModelMap().put("announceDate", announceDate);
                mv.getModelMap().put("submitLastdate", submitLastdate);
                mv.getModelMap().put("contactPerson", contactPerson);
                mv.getModelMap().put("tenderPhase", tenderPhase);
                mv.getModelMap().put("totalVendor", vendor_total);
            }
        }
        mv.getModelMap().put("list1", committeeList);

        mv.setViewName("Tender/ApprovedTechnicalBidList");
        return mv;

    }

