    public ModelAndView addSapItemSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();
        String tenderPhase = request.getParameter("tenderPhase");
        String tender_no = request.getParameter("tender_no");
        String ref_no = request.getParameter("ref_no");

        String[] checkId = request.getParameterValues("checkId");
        for (String checkedValues : checkId) {

            SapTenderItem sapTenderItem = sapTenderItemService.readId(Integer.parseInt(checkedValues));
            // SapTenderItem sapTenderItem = sapTenderItemService.readById(Integer.SIZE);

            List tenderItemMaster1 = tenderItemMasterService.readByRefNo(ref_no);
            String srNo = "";
            String s_no = "";
            for (Object o : tenderItemMaster1) {
                TenderItemMaster tim = (TenderItemMaster) o;
                s_no = tim.getSrNo();
            }

            if (s_no.equals("")) {
                srNo = "1";
            } else {
                srNo = (Integer.parseInt(s_no) + 1) + "";
            }

            TenderItemMaster tenderItemMaster = new TenderItemMaster();
            tenderItemMaster.setRefNo(ref_no);
            tenderItemMaster.setItemCode(sapTenderItem.getItemCode());
            tenderItemMaster.setItemDescription(sapTenderItem.getItemDesc());
            tenderItemMaster.setRemark("");
            tenderItemMaster.setUom(sapTenderItem.getUom());
            tenderItemMaster.setQty(sapTenderItem.getQty());
            tenderItemMaster.setDeliveryScheduleDate(sapTenderItem.getDeliSch());
            tenderItemMaster.setDeliveryScheduleQty(sapTenderItem.getDeliSch());
            tenderItemMaster.setRemark(sapTenderItem.getDeliSch());
            tenderItemMaster.setLocation("");
            tenderItemMaster.setPurNo(ref_no);
            tenderItemMaster.setItemNo("");
            // tenderItemMaster.setSrNo(sapTenderItem.getSrNo());
            tenderItemMaster.setSrNo(srNo);
            tenderItemMaster.setPrNo(sapTenderItem.getPrNo());
            tenderItemMasterService.create(tenderItemMaster);

            //--------------Vendor added
            List tenderItemMaster11 = tenderItemMasterService.readByItemCode(sapTenderItem.getItemCode());

            String tender_no1 = "";
            int tender_id = 0;
            for (Object o : tenderItemMaster11) {
                TenderItemMaster vtbi = (TenderItemMaster) o;
                tender_no1 = vtbi.getRefNo();
                TenderMaster tenderMaster1 = tenderMasterService.readRefNo(tender_no1);
                int bid_open_flag = tenderMaster1.getOpenBidFlag();

                if (bid_open_flag == 1) {
                    tender_id = tenderMaster1.getId();
                    break;
                }
            }

            List tenderVendor = tenderVendorService.vendorList(tender_no1);

            for (Object o : tenderVendor) {
                TenderVendor tv = (TenderVendor) o;
                String vendor_code = tv.getVendorCode();
                String vendor_name = tv.getVendorName();
                String address = tv.getAddress();
                String email_id = tv.getEmailId();
                String mobile_no = tv.getMobileNo();

                List tenderVendor1 = tenderVendorService.readByRefVendor(ref_no, vendor_code);

                if (tenderVendor1.isEmpty()) {
                    TenderVendor tenderVendor11 = new TenderVendor();
                    tenderVendor11.setRfqNo(ref_no);
                    tenderVendor11.setRefNo(ref_no);
                    tenderVendor11.setVendorCode(vendor_code);
                    tenderVendor11.setVendorName(vendor_name);
                    tenderVendor11.setAddress(address);
                    tenderVendor11.setEmailId(email_id);
                    tenderVendor11.setMobileNo(mobile_no);
                    tenderVendor11.setChecked(0);
                    tenderVendorService.create(tenderVendor11);
                }

            }

            //-------------------------
        }

        List tenderItemMaster = tenderItemMasterService.readByRefNo(ref_no);

        mv.getModelMap().put("tenderItemMaster", tenderItemMaster);

        //    List list = employeeMasterService.readByDrow();
        //    request.setAttribute("list", list);
        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        EmployeeMaster employeeMaster = employeeMasterService.readUser(username);

        String department = employeeMaster.getDepartment();
        String location = employeeMaster.getLocation();

        ServiceRights serviceRights = serviceRightsService.ReadDepartmentLocation(department, location);

        mv.getModelMap().put("serviceRights", serviceRights);

        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.getModelMap().put("ref_no", ref_no);

        List plantMaster = plantMasterService.read();

        mv.getModelMap().put("plantMaster", plantMaster);

        mv.getModelMap().put("tenderPhase", tenderPhase);
        mv.setViewName("Tender/AddSapItem");
        return mv;
    }

