                    tenderItenMaster.setItemDescription(ITEMDESCRIPTIONN);
                    tenderItenMaster.setRemark(ITEMDETAILSS);
                    tenderItenMaster.setDeliveryScheduleDate(PURPOSEE);
                    tenderItenMaster.setDeliveryScheduleQty(ITEMDETAILSS);
