        mv.getModelMap().put("tenderItemMaster1", tenderItemMaster1);

        List vendorTechnicalBid = vendorTechnicalBidService.techBidOpenList1(ref_no);

        for (Object o : vendorTechnicalBid) {
            VendorTechnicalBid vtb = (VendorTechnicalBid) o;
            vtb.setReviseBidFlag(0);
            vendorTechnicalBidService.update(vtb);

            //send mail to vendor
        }

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
