    public ModelAndView searchUserForCommitteeList(HttpServletRequest request, HttpServletResponse response) throws Exception {

        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();
        String tenderPhase = request.getParameter("tenderPhase");
        String id = request.getParameter("userList1");
        String ref_no = request.getParameter("ref_no");
        String bid_type = request.getParameter("bid_type");

        try {

            CommitteeApprovalSetting appSetting = committeeApprovalSettingService.readById(Integer.parseInt(id));

            List<EmployeeMaster> empByData = new ArrayList<>();

            List<?> committeeUser = committeeApprovalUserService.readByIdToList1(id);

            ListIterator<CommitteeApprovalUser> itr = (ListIterator<CommitteeApprovalUser>) committeeUser.listIterator();

            tenderCommitteeService.deleteByRefNo(ref_no, bid_type);

            while (itr.hasNext()) {
                CommitteeApprovalUser s = itr.next();

                EmployeeMaster userList = employeeMasterService.read(s.getUserId());

                String employee_code = userList.getEmployeeCode();
                String employee_name = userList.getName();

                TenderCommittee tenderCommittee = new TenderCommittee();

                tenderCommittee.setTenderNo(ref_no);
                tenderCommittee.setUserId(employee_code);
                tenderCommittee.setFullName(employee_name);
                tenderCommittee.setBidType(Integer.parseInt(bid_type));
                tenderCommittee.setBidOpenStatus(0);
                tenderCommitteeService.create(tenderCommittee);

                empByData.add(userList);
            }

            List tenderCommittee1 = tenderCommitteeService.readByRefNo(ref_no, bid_type);
            mv.getModelMap().put("tenderCommittee1", tenderCommittee1);

            mv.getModelMap().put("tenderMaster", tenderMaster);
            mv.getModelMap().put("bid_type", bid_type);
            mv.getModelMap().addAttribute("committeeUser", committeeUser);
            mv.getModelMap().addAttribute("submitData", "1");
            request.setAttribute("empByData", empByData);
            request.setAttribute("length", empByData.size());

        } catch (Exception e11) {
        }
        request.setAttribute("id", id);

        mv.setViewName("forward:tenderMaster.htm?act=searchUserForCommittee");
//        mv.setViewName("Tender/SearchUserForCommittee");
        return mv;
    }

