    public ModelAndView liveTenderList(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String location = employeeMaster.getLocation();
        String department = employeeMaster.getDepartment();

        UserRights userRights = userRightsService.readByUser(username);
        int authuser = userRights.getAuthorizeTender();

        if (authuser == 0) {
            List list = tenderMasterService.liveTenderList(username, location, department);

            List list1 = tenderMasterService.liveTenderList1(username, location, department);

            List list2 = tenderMasterService.liveTenderUnautorizeList(username, location, department);

            //         List list3 = tenderMasterService.liveTenderList3(username, location, department);
            //       List list4 = tenderMasterService.liveTenderList4(username, location, department);
            List list3 = tenderMasterService.liveTenderAuthorizerList3(username, location, department);

            List list4 = tenderMasterService.liveTenderAuthorizerList4(username, location, department);

            request.setAttribute("list", list);

            mv.getModelMap().put("list", list);
            mv.getModelMap().put("list1", list1);
            mv.getModelMap().put("list2", list2);
            mv.getModelMap().put("list3", list3);
            mv.getModelMap().put("list4", list4);
        } else {
            List list = tenderMasterService.liveTenderAuthorizerList(username, location, department);

            List list1 = tenderMasterService.liveTenderAuthorizerList1(username, location, department);

            List list2 = tenderMasterService.liveTenderUnautorizeList(username, location, department);

            List list3 = tenderMasterService.liveTenderAuthorizerList3(username, location, department);

            List list4 = tenderMasterService.liveTenderAuthorizerList4(username, location, department);

            request.setAttribute("list", list);

            mv.getModelMap().put("list", list);
            mv.getModelMap().put("list1", list1);
            mv.getModelMap().put("list2", list2);
            mv.getModelMap().put("list3", list3);
            mv.getModelMap().put("list4", list4);
        }
        if (session != null) {

            String successMessage = (String) session.getAttribute("successMessage");
            if (successMessage != null) {
                mv.addObject("successMessage", successMessage);
                session.removeAttribute("successMessage");
            }

            String failureMessage = (String) session.getAttribute("failureMessage");
            if (failureMessage != null) {
                mv.addObject("failureMessage", failureMessage);
                session.removeAttribute("failureMessage");
            }
        }
        mv.getModelMap().put("authuser", authuser);
        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.setViewName("Tender/LiveTenderList");
        return mv;
    }

