    public void extendDateSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {

        response.setContentType("text/plain");
        response.setCharacterEncoding("UTF-8");

        try {

            String refNo = request.getParameter("refNo");

            TenderMaster tenderMaster = tenderMasterService.readRefNo(refNo);
            String title = tenderMaster.getTitle();
            String announceDate = tenderMaster.getAnnounceDate();
            String docCost = tenderMaster.getDocCost();

            String submitLastdate1 = request.getParameter("submitLastdate1");
            String submitLastdate = request.getParameter("submitLastdate");

            SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            Date d1 = sdf.parse(submitLastdate1);
            Date d2 = sdf.parse(submitLastdate);

            // Technical Bid Validation
            if (tenderMaster.getTenderPhase() == 2) {

                boolean bidOpen = vendorTechnicalBidService.readByRefNO(refNo);

                if (bidOpen) {

                    response.getWriter().write("FAIL:The tender due date cannot be extended because the technical bid has already been opened.");
                    return;
                }
            }

            // Date Validation
            long difference = d2.getTime() - d1.getTime();

            if (difference < 0) {

                response.getWriter().write("FAIL:Tender Due Date cannot be less than current due date.");
                return;
            }

            HttpSession session = request.getSession(false);
            UserMaster user = (UserMaster) session.getAttribute("user");

            String username = user.getLoginName();

            EmployeeMaster employeeMaster = employeeMasterService.read(username);

            String location = employeeMaster.getLocation();
            String department = employeeMaster.getDepartment();

            UserRights userRights = userRightsService.readByUser(username);

            // Update Date
            tenderMasterService.updateDate(refNo, submitLastdate);

            // Send Mail
            List list = tenderVendorService.readByRefNo(refNo);

            for (Object o : list) {

                TenderVendor tv = (TenderVendor) o;

                String email_id = tv.getEmailId();
                String vendor_code = tv.getVendorCode();

                String[] mails = email_id.split(",");

                for (String mail : mails) {

                    EmailTemplate emailTemplate = emailTemplateService.readById(12);

                    String subject = emailTemplate.getSubject();
                    String msg = emailTemplate.getBodytext();

                    subject = subject.replace("{location}", location.toUpperCase());

                    msg = msg.replace("{tender_title}", title.toUpperCase());
                    msg = msg.replace("{ref_no}", refNo);
                    msg = msg.replace("{start_date}", announceDate);
                    msg = msg.replace("{end_date}", submitLastdate);
                    msg = msg.replace("{fee}", docCost);
                    msg = msg.replace("{vendor_code}", vendor_code);
                    msg = msg.replace("{location}", location.toUpperCase());
                    msg = msg.replace("{department}", department);

                    SendMail sendMail = new SendMail();
                    sendMail.sendMail("", mail, subject, msg);
                }
            }

            // Log
            UserMaster user11 = (UserMaster) session.getAttribute("user");

            LogsMaster lm = new LogsMaster();

            Date date = new Date();

            lm.setlDate(dateFormat.format(date))
                    .setTime(timeFOrmat.format(date))
                    .setUserName(user11.getUserFullName())
                    .setIp(myIp)
                    .setAction("Tender Extend Date for tender no " + refNo)
                    .setDrow("Y");

            logService.create(lm);

            // Follow Up
            LocalDateTime now = LocalDateTime.now();

            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");

            TenderFollowup followup = new TenderFollowup();

            followup.setActivityDate(now.format(formatter));
            followup.setActivity("Tender Extend Date for tender no " + refNo);
            followup.setLocation(location);
            followup.setTenderNo(refNo);
            followup.setPerson(user11.getLoginName());
            followup.setPersonFullname(user11.getUserFullName());

            tenderFollowupService.create(followup);

            // Success
            response.getWriter().write("SUCCESS:Tender Extend Date successfully.");

        } catch (Exception e) {

            e.printStackTrace();

            response.getWriter().write("ERROR:" + e.getMessage());

        }
    }

