                AuthTenderMaster authTenderMaster = new AuthTenderMaster();
                authTenderMaster.setRefNo(refNo);
                authTenderMaster.setTitle(title1);
                authTenderMaster.setCategoryId(category_id1);
                authTenderMaster.setValue(value1);
                authTenderMaster.setEmd(emd1);
                authTenderMaster.setDocCost(doc_cost1);
                authTenderMaster.setType(type1);
                authTenderMaster.setContactPerson(contact_person1);
                authTenderMaster.setLocation(location1);
                authTenderMaster.setAnnounceDate(announce_date1);
                authTenderMaster.setCollectionLastdate(collection_lastdate1);
                authTenderMaster.setSubmitLastdate(submit_lastdate1);
                authTenderMaster.setWorkDesc(work_desc1);
                authTenderMaster.setTenderRemark(tender_remark1);
                authTenderMaster.setTenderAdmin(tender_admin1);
                authTenderMaster.setTenderAdminContactNumber(tender_admin_contact_number1);
                authTenderMaster.setTenderAuthorizePerson(tender_authorize_person1);
                authTenderMaster.setTenderAuthorizeContactNo(tender_authorize_contact_no1);
                authTenderMaster.setAuthorizeFlag(authorize_flag1);
                authTenderMaster.setTenderAuthorizeUserName(tender_authorize_user_name1);
                authTenderMaster.setReAuthoFlag(re_autho_flag1);
                authTenderMaster.setIsInAuthoTable(is_in_autho_table1);
                authTenderMaster.setVendorFlag(vendor_flag1);
                authTenderMaster.setItemFlag(item_flag1);
                authTenderMaster.setEmailFlag(email_flag1);
                authTenderMaster.setAuthorizeDate(authorize_date1);
                authTenderMaster.setReturnFlag(return_flag1);
                authTenderMaster.setDeleteFlag(delete_flag1);
                authTenderMaster.setTenderPhase(tender_phase1);
