    public ModelAndView receiveBidListAjax(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String userName = user.getLoginName();

        int draw = Integer.parseInt(request.getParameter("draw"));
        int start = Integer.parseInt(request.getParameter("start"));
        int length = Integer.parseInt(request.getParameter("length"));

        String searchValue = request.getParameter("search[value]");

        String orderColumnIndex = request.getParameter("order[0][column]");
        String orderDir = request.getParameter("order[0][dir]");

        if (orderDir == null || orderDir.trim().equals("")) {
            orderDir = "desc";
        }

        if (orderColumnIndex == null || orderColumnIndex.trim().equals("")) {
            orderColumnIndex = "0";
        }

        String orderColumn = "id";

        switch (orderColumnIndex) {

            case "0":
                orderColumn = "id";
                break;

            case "1":
                orderColumn = "refNo";
                break;

            case "2":
                orderColumn = "title";
                break;

            case "3":
                orderColumn = "announceDate";
                break;

            case "4":
                orderColumn = "submitLastdate";
                break;

            case "5":
                orderColumn = "contactPerson";
                break;

            case "6":
                orderColumn = "tenderPhase";
                break;

            default:
                orderColumn = "id";
                break;
        }

        List list = tenderMasterService.getReceiveTechBidListPagination(start, length, userName, searchValue, orderColumn, orderDir);

        int totalRecords = tenderMasterService.getReceiveTechBidListCount(userName);

        int filteredRecords = tenderMasterService.getFilteredReceiveTechBidListCount(userName, searchValue);

        JSONArray data = new JSONArray();

        int srNo = start + 1;

        for (Object obj : list) {

            TenderMaster tm = (TenderMaster) obj;

            JSONObject row = new JSONObject();

            String refNo = tm.getRefNo();
            int tenderPhase = tm.getTenderPhase();

            String tenderDueDate = tm.getSubmitLastdate();
            String bidStatus = "0";

            String preBidOpenFlag = "0";
            String preBidApproveFlag = "0";

            String techBidOpenFlag = "0";
            String techBidApproveFlag = "0";

            String priceBidOpenFlag = "0";

            SimpleDateFormat sdf
                    = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            Date currentDate = new Date();

            try {

                Date dueDate = sdf.parse(tenderDueDate);

                if (dueDate.before(currentDate)) {
                    bidStatus = "1";
                }

            } catch (Exception e) {
                e.printStackTrace();
            }

            int vendorTotal = 0;

            List vendorList = tenderVendorService.vendorList(refNo);

            if (vendorList != null) {
                vendorTotal = vendorList.size();
            }

            int totalBid = 0;

            List bidList = vendorTenderBidService.vendorList(refNo);

            if (bidList != null) {

                for (Object o : bidList) {

                    totalBid++;

                    try {

                        VendorTenderBid vtb = (VendorTenderBid) o;

                        if ("1".equals(vtb.getBidOpenFlag())) {
                            priceBidOpenFlag = "1";
                        }

                        String reviseDate = vtb.getReviseDateTime();

                        if (reviseDate != null && !reviseDate.trim().equals("")) {

                            tenderDueDate = reviseDate;

                            Date revisedDate = sdf.parse(reviseDate);

                            bidStatus = "0";

                            if (revisedDate.before(currentDate)) {
                                bidStatus = "1";
                            }
                        }

                    } catch (Exception ex) {
                        ex.printStackTrace();
                    }
                }
            }

            if (tenderPhase == 2) {

                if (tm.getTechBidOpenFlag() == 0) {

                    List techVendorList = vendorTenderBidService.vendorTechBidList(refNo);

                    if (techVendorList != null) {
                        totalBid += techVendorList.size();
                    }
                }
            }

            int totalRegret = 0;

            List regretList = tenderRegretService.regretList(refNo);

            if (regretList != null) {
                totalRegret = regretList.size();
            }

            if (tenderPhase == 3) {

                List preBidList = vendorPreBidService.vendorList(refNo);

                if (preBidList != null) {

                    for (Object o : preBidList) {

                        try {

                            VendorPreBid vpb
                                    = (VendorPreBid) o;

                            if ("1".equals(vpb.getBidOpenFlag())) {
                                preBidOpenFlag = "1";
                            }

                            if ("1".equals(vpb.getBidApproveFlag())) {
                                preBidApproveFlag = "1";
                            }

                        } catch (Exception ex) {
                            ex.printStackTrace();
                        }
                    }
                }
            }

            if (tenderPhase == 2 || tenderPhase == 3) {

                List techBidList = vendorTechnicalBidService.vendorList(refNo);

                if (techBidList != null) {

                    for (Object o : techBidList) {

                        try {

                            VendorTechnicalBid vtb
                                    = (VendorTechnicalBid) o;

                            if ("1".equals(vtb.getBidOpenFlag())) {
                                techBidOpenFlag = "1";
                            }

                            if ("1".equals(vtb.getBidApproveFlag())) {
                                techBidApproveFlag = "1";
                            }

                        } catch (Exception ex) {
                            ex.printStackTrace();
                        }
                    }
                }
            }

            String vendorTotalHtml
                    = "<a href='javascript:void(0);' "
                    + "onclick=\"loadBitSentVendor('"
                    + refNo
                    + "')\">"
                    + vendorTotal
                    + "</a>";

            String bidReceivedHtml
                    = "<a href='javascript:void(0);' "
                    + "onclick=\"loadBidRRVendor('"
                    + refNo
                    + "')\">"
                    + totalBid
                    + "/"
                    + totalRegret
                    + "</a>";

            StringBuilder bidStatusHtml = new StringBuilder();

            if ("1".equals(bidStatus)) {

                if (tenderPhase == 3 && "1".equals(preBidApproveFlag) && "0".equals(techBidOpenFlag)) {

                    bidStatusHtml.append(
                            "<a href='tenderMaster.htm?act=techBidOpenView&id="
                            + tm.getId()
                            + "'>Tech. bid yet to be open</a><br><br>");
                }

                if (tenderPhase == 2 && "0".equals(techBidOpenFlag)) {

                    bidStatusHtml.append(
                            "<a href='tenderMaster.htm?act=techBidOpenView&id="
                            + tm.getId()
                            + "'>Tech. bid yet to be open</a><br><br>");
                }

                if ("1".equals(techBidOpenFlag)) {

                    bidStatusHtml.append(
                            "<a href='tenderMaster.htm?act=techBidOpenView&id="
                            + tm.getId()
                            + "'>Tech. bid open</a><br><br>");
                }
            }

            row.put("srNo", srNo++);
            row.put("refNo", refNo);
            row.put("title", tm.getTitle());
            row.put("tenderDate", tm.getAnnounceDate());
            row.put("tenderDueDate", tenderDueDate);
            row.put("createdBy", tm.getContactPerson());
            row.put("tenderPhase", tenderPhase + " Part");
            row.put("vendorTotal", vendorTotalHtml);
            row.put("bidReceived", bidReceivedHtml);
            row.put("bidStatus", bidStatusHtml.toString());

            data.put(row);
        }

        JSONObject result = new JSONObject();

        result.put("draw", draw);
        result.put("recordsTotal", totalRecords);
        result.put("recordsFiltered", filteredRecords);
        result.put("data", data);

        response.setContentType("application/json");
        response.getWriter().write(result.toString());

        return null;
    }

    public void receiveBidReportExportExcel(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Session expired");
            return;
        }

        UserMaster user = (UserMaster) session.getAttribute("user");
        String userName = user.getLoginName();

        String searchValue = request.getParameter("searchValue");

        String orderColumn = "id";
        String orderDir = "asc";

        int start = 0;
        int filteredRecords = tenderMasterService.getFilteredReceiveTechBidListCount(userName, searchValue);

        List receiveBidReportList = tenderMasterService.getReceiveTechBidListPagination(start, filteredRecords, userName, searchValue, orderColumn, orderDir);

        Workbook workbook = new XSSFWorkbook();
        Sheet sheet = workbook.createSheet("Receive Bid Report");

        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBoldweight(Font.BOLDWEIGHT_BOLD);
        headerFont.setColor(IndexedColors.WHITE.getIndex());
        headerStyle.setFont(headerFont);
        headerStyle.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        XSSFColor headerColor = new XSSFColor(new java.awt.Color(31, 78, 120));
        ((XSSFCellStyle) headerStyle).setFillForegroundColor(headerColor);
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);

        CellStyle wrapStyle = workbook.createCellStyle();
        wrapStyle.setWrapText(true);
        wrapStyle.setVerticalAlignment(CellStyle.VERTICAL_TOP);

        String[] headers = {
            "Sr.No.", "Tender No.", "Project Name", "Tender Date", "Tender Due Date",
            "Created By", "Tender Type", "Bid Sent To No. Of Vendor",
            "Bid Received/Regret From No. Of Vendor", "Bid Status"
        };

        int rowNum = 0;
        int srNo = 1;

        Row headerRow = sheet.createRow(rowNum++);
        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        sheet.createFreezePane(0, 1);

        SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
        Date currentDate = new Date();

        if (receiveBidReportList != null) {

            for (Object obj : receiveBidReportList) {

                TenderMaster tm = (TenderMaster) obj;

                String refNo = tm.getRefNo();
                int tenderPhase = tm.getTenderPhase();

                String tenderDueDate = tm.getSubmitLastdate();
                String bidStatus = "0";

                String preBidApproveFlag = "0";
                String techBidOpenFlag = "0";

                try {
                    Date dueDate = sdf.parse(tenderDueDate);
                    if (dueDate.before(currentDate)) {
                        bidStatus = "1";
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }

                int vendorTotal = 0;
                List vendorList = tenderVendorService.vendorList(refNo);
                if (vendorList != null) {
                    vendorTotal = vendorList.size();
                }

                int totalBid = 0;
                List bidList = vendorTenderBidService.vendorList(refNo);

                if (bidList != null) {
                    for (Object o : bidList) {
                        totalBid++;
                        try {
                            VendorTenderBid vtb = (VendorTenderBid) o;

                            String reviseDate = vtb.getReviseDateTime();

                            if (reviseDate != null && !reviseDate.trim().equals("")) {
                                tenderDueDate = reviseDate;
                                Date revisedDate = sdf.parse(reviseDate);
                                bidStatus = "0";
                                if (revisedDate.before(currentDate)) {
                                    bidStatus = "1";
                                }
                            }

                        } catch (Exception ex) {
                            ex.printStackTrace();
                        }
                    }
                }

                if (tenderPhase == 2 && tm.getTechBidOpenFlag() == 0) {
                    List techVendorList = vendorTenderBidService.vendorTechBidList(refNo);
                    if (techVendorList != null) {
                        totalBid += techVendorList.size();
                    }
                }

                int totalRegret = 0;
                List regretList = tenderRegretService.regretList(refNo);
                if (regretList != null) {
                    totalRegret = regretList.size();
                }

                if (tenderPhase == 3) {
                    List preBidList = vendorPreBidService.vendorList(refNo);
                    if (preBidList != null) {
                        for (Object o : preBidList) {
                            try {
                                VendorPreBid vpb = (VendorPreBid) o;
                                if ("1".equals(vpb.getBidApproveFlag())) {
                                    preBidApproveFlag = "1";
                                }
                            } catch (Exception ex) {
                                ex.printStackTrace();
                            }
                        }
                    }
                }

                if (tenderPhase == 2 || tenderPhase == 3) {
                    List techBidList = vendorTechnicalBidService.vendorList(refNo);
                    if (techBidList != null) {
                        for (Object o : techBidList) {
                            try {
                                VendorTechnicalBid vtb = (VendorTechnicalBid) o;
                                if ("1".equals(vtb.getBidOpenFlag())) {
                                    techBidOpenFlag = "1";
                                }
                            } catch (Exception ex) {
                                ex.printStackTrace();
                            }
                        }
                    }
                }

                String bidStatusText = "";

                if ("1".equals(bidStatus)) {
                    if (tenderPhase == 3 && "1".equals(preBidApproveFlag) && "0".equals(techBidOpenFlag)) {
                        bidStatusText = "Tech. bid yet to be open";
                    } else if (tenderPhase == 2 && "0".equals(techBidOpenFlag)) {
                        bidStatusText = "Tech. bid yet to be open";
                    } else if ("1".equals(techBidOpenFlag)) {
                        bidStatusText = "Tech. bid open";
                    }
                }

                Row excelRow = sheet.createRow(rowNum++);
                excelRow.createCell(0).setCellValue(srNo++);
                excelRow.createCell(1).setCellValue(refNo != null ? refNo : "");
                excelRow.createCell(2).setCellValue(tm.getTitle() != null ? tm.getTitle() : "");
                excelRow.createCell(3).setCellValue(tm.getAnnounceDate() != null ? tm.getAnnounceDate() : "");
                excelRow.createCell(4).setCellValue(tenderDueDate != null ? tenderDueDate : "");
                excelRow.createCell(5).setCellValue(tm.getContactPerson() != null ? tm.getContactPerson() : "");
                excelRow.createCell(6).setCellValue(tenderPhase + " Part");
                excelRow.createCell(7).setCellValue(vendorTotal);
                excelRow.createCell(8).setCellValue(totalBid + "/" + totalRegret);
                excelRow.createCell(9).setCellValue(bidStatusText);
            }
        }

        for (int i = 0; i < headers.length; i++) {
            sheet.autoSizeColumn(i);
        }

        SimpleDateFormat fileDateFormat = new SimpleDateFormat("ddMMyyyy");
        String fileDate = fileDateFormat.format(new Date());
        String fileName = "Receive_Bid_Report_" + fileDate + ".xlsx";

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        OutputStream outputStream = response.getOutputStream();
        try {
            workbook.write(outputStream);
        } finally {
            outputStream.flush();
            outputStream.close();
        }
    }

