    public ModelAndView preBidOpenUserSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String id = request.getParameter("id");
        TenderMaster tenderMaster = tenderMasterService.readById(Integer.parseInt(id));

        String refNo = tenderMaster.getRefNo();
        String tender_department = tenderMaster.getDepartment();

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String location = employeeMaster.getLocation();
        String user_department1 = employeeMaster.getDepartment();

        String user_department2 = "";
        if (user_department1.equals("Finance")) {
            user_department2 = tender_department;
        } else {
            user_department2 = "Finance";
        }

        String vendor_list = request.getParameter("vendor_list");
        String username1 = request.getParameter("username1");
        String username2 = request.getParameter("username2");
        String password1 = request.getParameter("password1");
        String password2 = request.getParameter("password2");

        List list = userMasterService.checkUser(username1, password1, user_department1);
        List list1 = userMasterService.checkUser(username2, password2, user_department2);

        if (list.isEmpty()) {
            request.setAttribute("failureMessage",
                    "Information: Username password not match");
        } else {
            EmployeeMaster employeeMaster1 = employeeMasterService.read(username1);
            String user_by_id1 = employeeMaster1.getName();
            EmployeeMaster employeeMaster2 = employeeMasterService.read(username2);
            String user_by_id2 = employeeMaster2.getName();

            String user_by = "[" + username1 + "," + username2 + "]";
            String user_by_id = "[" + user_by_id1 + "," + user_by_id2 + "]";
            LocalDateTime myDateObj = LocalDateTime.now();
            DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
            String formattedDate = myDateObj.format(myFormatObj);

            //Commetee member updated
            tenderCommitteeService.updateStatus(refNo, username1, "3");

            List tenderCommittee = tenderCommitteeService.readByRefNo(refNo, "3");

            int flag = 0;
            for (Object o : tenderCommittee) {
                //i++;
                TenderCommittee tc = (TenderCommittee) o;
                int bid_open_status = tc.getBidOpenStatus();
                if (bid_open_status == 0) {
                    flag = 1;
                }
            }

            if (flag == 0) {
                String[] checkId = vendor_list.split(":");
                for (String checkedValues : checkId) {
                    vendor_list = checkedValues;
                    vendorPreBidService.openPreBid(refNo, vendor_list, user_by, user_by_id, formattedDate);

                    //HttpSession session = request.getSession(false);
                    UserMaster user11 = (UserMaster) session.getAttribute("user");
                    LogsMaster lm = new LogsMaster();
                    Date date = new Date();
                    lm.setlDate(dateFormat.format(date)).setTime(timeFOrmat.format(date)).setUserName(user11.getUserFullName()).setIp(myIp).setAction("Tender Pre Qualiication Bid open for tender no " + refNo + " vednor " + vendor_list + "").setDrow("Y");
                    logService.create(lm);

                    LocalDateTime myDateObj1 = LocalDateTime.now();
                    DateTimeFormatter myFormatObj1 = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
                    String formattedDate1 = myDateObj1.format(myFormatObj1);

                    TenderFollowup tenderFollowup = new TenderFollowup();
                    tenderFollowup.setActivityDate(formattedDate1);
                    tenderFollowup.setActivity("Tender Pre Qualfication Bid Open for tender no " + refNo + " Vendor Code " + vendor_list + "");
                    tenderFollowup.setLocation(location);
                    tenderFollowup.setTenderNo(refNo);
                    tenderFollowup.setPerson(user_by_id);
                    tenderFollowup.setPersonFullname(user_by);
                    tenderFollowupService.create(tenderFollowup);

                }
            }
            request.setAttribute("successMessage",
                    "Information: bid open successfully");

        }

        List tenderCommittee1 = tenderCommitteeService.readByRefUser(refNo, username, "3");
        int bid_open_flag = 0;
        for (Object o : tenderCommittee1) {
            //i++;
            TenderCommittee tc = (TenderCommittee) o;
            bid_open_flag = tc.getBidOpenStatus();
        }

        if (bid_open_flag == 0) {
            List list2 = vendorPreBidService.preBidList(refNo);
            mv.getModelMap().put("list", list2);
        }

        List list3 = vendorPreBidService.preBidOpenList(refNo);

        request.setAttribute("refNo", refNo);

        mv.getModelMap().put("id", id);
        mv.getModelMap().put("refNo", refNo);

        mv.getModelMap().put("list1", list3);
        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.setViewName("Tender/PreBidOpenView");
        return mv;

    }

