    public ModelAndView priceBidOpenView(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String id = request.getParameter("id");
        TenderMaster tenderMaster = tenderMasterService.readById(Integer.parseInt(id));

        String refNo = tenderMaster.getRefNo();
        String prNo = tenderMaster.getPrNo();
        int omsPrFlag = 4;
        OmsMaster omsMaster = omsMasterService.readByPrNo(prNo, omsPrFlag);
        if (omsMaster != null) {
            mv.getModelMap().put("omsMaster", omsMaster);
        }
        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        List tenderCommittee2 = tenderCommitteeService.readByRefNo(refNo, "1");
        mv.getModelMap().put("tenderCommittee2", tenderCommittee2);

        List tenderCommittee1 = tenderCommitteeService.readByRefUser(refNo, username, "1");
        int bid_open_flag = 0;

        if (!tenderCommittee1.isEmpty()) {
            for (Object o : tenderCommittee1) {
                TenderCommittee tc = (TenderCommittee) o;
                bid_open_flag = tc.getBidOpenStatus();
            }

            if (bid_open_flag == 0) {
                List list = vendorTenderBidService.priceBidList(refNo);
                mv.getModelMap().put("list", list);
            }

            List list1 = vendorTenderBidService.priceBidOpenList(refNo);
            mv.getModelMap().put("list1", list1);
        }

        request.setAttribute("refNo", refNo);

        mv.getModelMap().put("id", id);
        mv.getModelMap().put("refNo", refNo);

        if (session != null) {

            String successMessage = (String) session.getAttribute("successMessage");
            if (successMessage != null) {
                mv.addObject("successMessage", successMessage);
                session.removeAttribute("successMessage");
            }

            String failureMessage = (String) session.getAttribute("failureMessage");
            if (failureMessage != null) {
                mv.addObject("failureMessage", failureMessage);
                session.removeAttribute("failureMessage");
            }
        }

        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.setViewName("Tender/PriceBidOpenView");
        return mv;
    }

