    public ModelAndView addTechnicalFileDetailsSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String vendorCode = request.getParameter("vendorCode");
        String refNo = request.getParameter("refNo");

        String RefNo = refNo.replace("/", "");

        String path = getServletContext().getRealPath("/")
                + File.separator + "StorageYard" + File.separator + "Tender"
                + File.separator + RefNo + File.separator + vendorCode;
        File f1 = new File(path);
        if (!f1.exists()) {
            f1.mkdirs();
        }

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String userName = user.getLoginName();

        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String dateTime = myDateObj.format(myFormatObj);

        String generalfile = request.getParameter("generalsfiles");
        if (generalfile == null) {
            generalfile = "";
        }

        MultipartHttpServletRequest multipartRequest = (MultipartHttpServletRequest) request;

        List<MultipartFile> files = multipartRequest.getFiles("generalsfiles");
        for (MultipartFile multipartFile : files) {
            if (multipartFile != null && multipartFile.getSize() > 0) {
                try {
                    String fileLocationURL = getServletContext().getRealPath("/")
                            + File.separator + "StorageYard" + File.separator + "Tender"
                            + File.separator + RefNo + File.separator + vendorCode + File.separator;
                    File photoFile = new File(fileLocationURL + multipartFile.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", ""));
                    generalfile = multipartFile.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", "").replaceAll("&", "");
                    multipartFile.transferTo(photoFile);
                    //    vendorInformation.setTermsConditionFile(photoFile+"");
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }

            if (generalfile.equals("")) {
            } else {
                TechnicalMultiAttachment technicalMultiAttachment = new TechnicalMultiAttachment();
                technicalMultiAttachment.setRefNo(refNo);
                technicalMultiAttachment.setAttachment(generalfile);
                technicalMultiAttachment.setVendorCode(vendorCode);
                technicalMultiAttachment.setDateTime(dateTime);
                technicalMultiAttachment.setTechnicalPersonName(userName);
                technicalMultiAttachmentService.create(technicalMultiAttachment);
            }

        }

        List technicalDocument = technicalMultiAttachmentService.readByRefNoVendorCode(refNo, vendorCode);

        mv.getModelMap().put("technicalDocument", technicalDocument);
        mv.getModelMap().put("refNo", refNo);
        mv.getModelMap().put("vendorCode", vendorCode);

        mv.setViewName("Tender/AjaxAddTechnicalFileDetails");
        return mv;
    }

