    public ModelAndView pastTenderPaginationAjax(HttpServletRequest request, HttpServletResponse response) throws Exception {

        int draw = Integer.parseInt(request.getParameter("draw"));
        int start = Integer.parseInt(request.getParameter("start"));
        int length = Integer.parseInt(request.getParameter("length"));

        String searchValue = request.getParameter("search[value]");

        String tender_no = request.getParameter("tender_no");
        String tender_title = request.getParameter("tender_title");
        String open_from_date = request.getParameter("open_from_date");
        String open_to_date = request.getParameter("open_to_date");
        String close_from_date = request.getParameter("close_from_date");
        String close_to_date = request.getParameter("close_to_date");

        String orderColumnIndex = request.getParameter("order[0][column]");
        String orderDir = request.getParameter("order[0][dir]");

        if (orderDir == null || orderDir.equals("")) {
            orderDir = "desc";
        }

        if (orderColumnIndex == null || orderColumnIndex.equals("")) {
            orderColumnIndex = "0";
        }

        String orderColumn = "id";

        switch (orderColumnIndex) {

            case "0":
                orderColumn = "id";
                break;

            case "1":
                orderColumn = "refNo";
                break;

            case "2":
                orderColumn = "title";
                break;

            case "3":
                orderColumn = "announceDate";
                break;

            case "4":
                orderColumn = "submitLastdate";
                break;

            default:
                orderColumn = "id";
                break;
        }

        List list = tenderMasterService.getPastTenderPagination(start, length, searchValue, tender_no, tender_title, open_from_date, open_to_date, close_from_date, close_to_date, orderColumn, orderDir);

        int totalRecords = tenderMasterService.getTotalPastTenderCount();

        int filteredRecords = tenderMasterService.getFilteredPastTenderCount(searchValue, tender_no, tender_title, open_from_date, open_to_date, close_from_date, close_to_date);

        JSONArray dataArray = new JSONArray();

        boolean isAsc = "asc".equalsIgnoreCase(orderDir);

        int srNo;

        if (isAsc) {

            srNo = filteredRecords - start;

        } else {

            srNo = start + 1;
        }

        for (Object obj : list) {

            TenderMaster tm = (TenderMaster) obj;

            JSONObject json = new JSONObject();

            if (isAsc) {

                json.put("srNo", srNo--);

            } else {

                json.put("srNo", srNo++);
            }

            String refNo = tm.getRefNo() != null ? tm.getRefNo() : "";

            int tenderPhase = tm.getTenderPhase();

            String tenderPhaseText = "";

            if (tenderPhase == 1) {

                tenderPhaseText = "Single Part";

            } else if (tenderPhase == 2) {

                tenderPhaseText = "Two Part";

            } else if (tenderPhase == 3) {

                tenderPhaseText = "Three Part";

            } else {

                tenderPhaseText = tenderPhase + " Part";
            }

            int vendor_total = 0;

            List vendorList = tenderVendorService.vendorList(refNo);

            if (vendorList != null) {

                vendor_total = vendorList.size();
            }

            int total_bid = 0;

            String price_bid_open_flag = "";

            List bidList = vendorTenderBidService.vendorList(refNo);

            if (bidList != null) {

                for (Object o1 : bidList) {

                    total_bid++;

                    VendorTenderBid vtb = (VendorTenderBid) o1;

                    String bidopen = vtb.getBidOpenFlag();

                    if (bidopen == null) {

                        bidopen = "";
                    }

                    if (bidopen.equals("1")) {

                        price_bid_open_flag = "1";
                    }
                }
            }

            int total_regret = 0;

            List regretList = tenderRegretService.regretList(refNo);

            if (regretList != null) {

                total_regret = regretList.size();
            }

            String bid_received = total_bid + "/" + total_regret;

            String bid_status = "0";

            String tender_due_date = tm.getSubmitLastdate();

            SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            SimpleDateFormat sdf1 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            SimpleDateFormat sdf2 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            Date sysdate1 = (Date) sdf.parse(tender_due_date);

            String sysdate = sdf1.format(sysdate1);

            Date submitdate = (Date) sdf1.parse(sysdate);

            Date sysdate12 = (Date) sdf.parse(tender_due_date);

            String sysdate122 = sdf2.format(sysdate12);

            Date submitdate2 = (Date) sdf2.parse(sysdate122);

            String currentdate = "";

            Date date = new java.util.Date();

            currentdate = sdf2.format(date);

            date = (Date) sdf2.parse(currentdate);

            if (submitdate2.before(date) && !submitdate2.equals(date)) {

                bid_status = "1";
            }

            TenderPriceApproval tenderPriceApproval = tenderPriceApprovalService.readByList(refNo);

            String approvalStatusText = "Approve Not Started";

            if (tenderPriceApproval != null) {

                int approvalStatus = tenderPriceApproval.getApprovalStatus();

                int approval_id = tenderPriceApproval.getId();

                bid_status = "0";

                if (approval_id > 0) {

                    if (approvalStatus == 0) {

                        bid_status = "1";

                        approvalStatusText = "In Approve";
                    }

                    if (approvalStatus == 1) {

                        bid_status = "2";

                        approvalStatusText = "Approved";
                    }

                    if (approvalStatus == 3) {

                        bid_status = "3";

                        approvalStatusText = "Recycled";
                    }
                }
            }

            json.put("refNo",
                    "<a href='tenderMaster.htm?act=tenderInfo&tender_no="
                    + refNo
                    + "' class='fw-600 text-break gradient-text'>"
                    + refNo
                    + "</a>"
            );

            json.put("title", tm.getTitle() != null ? tm.getTitle() : "");

            json.put("tender_date", tm.getAnnounceDate() != null ? tm.getAnnounceDate() : "");

            json.put("tender_due_date", tm.getSubmitLastdate() != null ? tm.getSubmitLastdate() : "");

            json.put("emd", tm.getEmd() != null ? tm.getEmd() : "");

            json.put("created_by", tm.getContactPerson() != null ? tm.getContactPerson() : "");

            json.put("tenderPhase", tenderPhaseText);

            json.put("vendor_total",
                    "<a href='#' "
                    + "class='fw-600 text-break gradient-text' "
                    + "onclick=\"loadBitSentVendor('"
                    + refNo
                    + "'); return false;\">"
                    + vendor_total
                    + "</a>"
            );

            json.put("bid_received",
                    "<a href='#' "
                    + "class='fw-600 text-break gradient-text' "
                    + "onclick=\"loadBidRRVendor('"
                    + refNo
                    + "'); return false;\">"
                    + bid_received
                    + "</a>"
            );

            json.put("bid_status_text",
                    "<a href='tenderMaster.htm?act=vendorListView&id="
                    + tm.getId()
                    + "' class='fw-600 text-break gradient-text'>"
                    + "Bid Opened"
                    + "</a>"
            );

            json.put("approval_status", approvalStatusText);

            dataArray.put(json);
        }

        JSONObject responseJson = new JSONObject();

        responseJson.put("draw", draw);

        responseJson.put("recordsTotal", totalRecords);

        responseJson.put("recordsFiltered", filteredRecords);

        responseJson.put("data", dataArray);

        response.setContentType("application/json");

        response.setCharacterEncoding("UTF-8");

        response.getWriter().write(responseJson.toString());

        return null;

    }

    public void pastTenderReportExportExcel(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Session expired");
            return;
        }

        UserMaster user = (UserMaster) session.getAttribute("user");
        String userName = user.getLoginName();

        String searchValue = request.getParameter("searchValue");

        String tender_no = request.getParameter("tender_no");
        String tender_title = request.getParameter("tender_title");
        String open_from_date = request.getParameter("open_from_date");
        String open_to_date = request.getParameter("open_to_date");
        String close_from_date = request.getParameter("close_from_date");
        String close_to_date = request.getParameter("close_to_date");

        String orderColumn = "id";
        String orderDir = "asc";

        int start = 0;
        int filteredRecords = tenderMasterService.getFilteredPastTenderCount(searchValue, tender_no, tender_title, open_from_date, open_to_date, close_from_date, close_to_date);

        List bidOpenTenderReportList = tenderMasterService.getPastTenderPagination(start, filteredRecords, searchValue, tender_no, tender_title, open_from_date, open_to_date, close_from_date, close_to_date, orderColumn, orderDir);

        Workbook workbook = new XSSFWorkbook();
        Sheet sheet = workbook.createSheet("Past Tender Report");

        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBoldweight(Font.BOLDWEIGHT_BOLD);
        headerFont.setColor(IndexedColors.WHITE.getIndex());
        headerStyle.setFont(headerFont);
        headerStyle.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        XSSFColor headerColor = new XSSFColor(new java.awt.Color(31, 78, 120));
        ((XSSFCellStyle) headerStyle).setFillForegroundColor(headerColor);
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);

        CellStyle wrapStyle = workbook.createCellStyle();
        wrapStyle.setWrapText(true);
        wrapStyle.setVerticalAlignment(CellStyle.VERTICAL_TOP);

        String[] headers = {
            "Sr.No.", "Tender No.", "Project Name", "Tender Date", "Tender Due Date",
            "EMD", "Created By", "Tender Type", "Bid Sent To No. Of Vendor",
            "Bid Received/Regret", "Bid Status", "Approval Status"
        };

        int rowNum = 0;
        int srNo = 1;

        Row headerRow = sheet.createRow(rowNum++);
        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        sheet.createFreezePane(0, 1);

        if (bidOpenTenderReportList != null) {

            for (Object obj : bidOpenTenderReportList) {

                TenderMaster tm = (TenderMaster) obj;

                String refNo = tm.getRefNo() != null ? tm.getRefNo() : "";

                int tenderPhase = tm.getTenderPhase();

                String tenderPhaseText;

                if (tenderPhase == 1) {
                    tenderPhaseText = "Single Part";
                } else if (tenderPhase == 2) {
                    tenderPhaseText = "Two Part";
                } else if (tenderPhase == 3) {
                    tenderPhaseText = "Three Part";
                } else {
                    tenderPhaseText = tenderPhase + " Part";
                }

                int vendorTotal = 0;
                List vendorList = tenderVendorService.vendorList(refNo);
                if (vendorList != null) {
                    vendorTotal = vendorList.size();
                }

                int totalBid = 0;
                List bidList = vendorTenderBidService.vendorList(refNo);

                if (bidList != null) {
                    for (Object o1 : bidList) {
                        totalBid++;
                    }
                }

                int totalRegret = 0;
                List regretList = tenderRegretService.regretList(refNo);
                if (regretList != null) {
                    totalRegret = regretList.size();
                }

                String bidReceived = totalBid + "/" + totalRegret;

                String bidStatusText = "Bid Opened";

                TenderPriceApproval tenderPriceApproval = tenderPriceApprovalService.readByList(refNo);

                String approvalStatusText = "Approve Not Started";

                if (tenderPriceApproval != null) {

                    int approvalStatus = tenderPriceApproval.getApprovalStatus();
                    int approvalId = tenderPriceApproval.getId();

                    if (approvalId > 0) {

                        if (approvalStatus == 0) {
                            approvalStatusText = "In Approve";
                        }

                        if (approvalStatus == 1) {
                            approvalStatusText = "Approved";
                        }

                        if (approvalStatus == 3) {
                            approvalStatusText = "Recycled";
                        }
                    }
                }

                Row excelRow = sheet.createRow(rowNum++);
                excelRow.createCell(0).setCellValue(srNo++);
                excelRow.createCell(1).setCellValue(refNo);
                excelRow.createCell(2).setCellValue(tm.getTitle() != null ? tm.getTitle() : "");
                excelRow.createCell(3).setCellValue(tm.getAnnounceDate() != null ? tm.getAnnounceDate() : "");
                excelRow.createCell(4).setCellValue(tm.getSubmitLastdate() != null ? tm.getSubmitLastdate() : "");
                excelRow.createCell(5).setCellValue(tm.getEmd() != null ? tm.getEmd() : "");
                excelRow.createCell(6).setCellValue(tm.getContactPerson() != null ? tm.getContactPerson() : "");
                excelRow.createCell(7).setCellValue(tenderPhaseText);
                excelRow.createCell(8).setCellValue(vendorTotal);
                excelRow.createCell(9).setCellValue(bidReceived);
                excelRow.createCell(10).setCellValue(bidStatusText);
                excelRow.createCell(11).setCellValue(approvalStatusText);
            }
        }

        for (int i = 0; i < headers.length; i++) {
            sheet.autoSizeColumn(i);
        }

        SimpleDateFormat fileDateFormat = new SimpleDateFormat("ddMMyyyy");
        String fileDate = fileDateFormat.format(new Date());
        String fileName = "Past_Tender_Report_" + fileDate + ".xlsx";

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        OutputStream outputStream = response.getOutputStream();
        try {
            workbook.write(outputStream);
        } finally {
            outputStream.flush();
            outputStream.close();
        }
    }

