    public void vendorListViewDownload(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        String refNo = request.getParameter("refNo");
        String id = request.getParameter("id");

        TenderPriceApproval tenderPriceApproval = tenderPriceApprovalService.readByList(refNo);
        String fileName = tenderPriceApproval.getAttachment();
        String RefNumber = refNo.replace("/", "");

        String certificateFileLocationURL = getServletContext().getRealPath("/")
                + File.separator + "StorageYard" + File.separator + "Tender"
                + File.separator + RefNumber + File.separator + fileName;

        request.setAttribute("filePath", certificateFileLocationURL);

        DownloadFile downloadFile = new DownloadFile();
        downloadFile.doDownload(request, response);

        mv.setViewName("forward:tenderMaster.htm?act=vendorListView&id=" + id);

    }

