            List vendorTechnicalBidTechAttachment1 = vendorTechnicalBidTechAttachmentService.readByVendorRefNo(refNo, vendor_code1);

            List vendorTechnicalBidTerms1 = vendorTechnicalBidTermsService.readByReviseVendorBid(refNo, vendor_code1, revise_technical_bid_id);
            List vendorTechnicalBidTermsAttachment1 = vendorTechnicalBidTermsAttachmentService.readByVendorRefNo(refNo, vendor_code1);

