    private synchronized void bidAutoOpen() throws Exception {
    //public ModelAndView retrieveAllVendor(HttpServletRequest request, HttpServletResponse response) throws Exception {

        ///    ModelAndView mv = new ModelAndView();
        //    TenderMaster tenderMaster = new TenderMaster();
        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String formattedDate = myDateObj.format(myFormatObj);

        DateTimeFormatter myFormatObj1 = DateTimeFormatter.ofPattern("dd-MM-yyyy");
        String submitLastdate = myDateObj.format(myFormatObj1);
        String submitLastdate1 = submitLastdate;
        String todaydate = submitLastdate + "";
        submitLastdate = submitLastdate + " 23:59:00";

        SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

        Date d1 = sdf.parse(formattedDate);
        Date d2 = sdf.parse(submitLastdate);

        long difference_In_Time
                = d2.getTime() - d1.getTime();

        String dt = submitLastdate1;  // Start date
        SimpleDateFormat sdf11 = new SimpleDateFormat("dd-MM-yyyy");
        Calendar c = Calendar.getInstance();
        c.setTime(sdf11.parse(dt));
        c.add(Calendar.DATE, 2);  // number of days to add
        dt = sdf11.format(c.getTime());
        submitLastdate1 = dt;
        submitLastdate = submitLastdate1 + "";

        List list = tenderMasterService.readNextTwoDayTender(todaydate, submitLastdate);

        for (Object o : list) {
            TenderMaster tm = (TenderMaster) o;
            String ref_no = tm.getRefNo();
            String location = tm.getLocation();
            String title = tm.getTitle();
            String department = tm.getDepartment();
            String announceDate = tm.getAnnounceDate();
            String submitLastdate2 = tm.getSubmitLastdate();
            String docCost = tm.getDocCost();
            int tenderphase = tm.getTenderPhase();

            List list1 = tenderVendorService.readByRefNo(ref_no);

            for (Object o1 : list1) {
                TenderVendor tv = (TenderVendor) o1;
                String vendor_code = tv.getVendorCode();
                String email_id = tv.getEmailId();

                String flag = "1";

                if (tenderphase == 1) {
                    flag = "0";
                    try {
                        VendorTenderBid vendorTenderBid = vendorTenderBidService.readByVendorRefNo(ref_no, vendor_code);
                        flag = vendorTenderBid.getSubmitFlag();
                        if (flag == null) {
                            flag = "0";
                        }
                    } catch (Exception e11) {
                    }

                }
                if (tenderphase == 2) {
                    flag = "0";
                    try {
                        VendorTenderBid vendorTenderBid = vendorTenderBidService.readByVendorRefNo(ref_no, vendor_code);
                        flag = vendorTenderBid.getTechSubmitFlag() + "";
                        if (flag == null) {
                            flag = "0";
                        }
                    } catch (Exception e11) {
                    }

                }

                try {
                    if (flag.equals("0")) {

                        EmailTemplate emailTemplate = emailTemplateService.readById(5);

                        String subject = emailTemplate.getSubject();
                        String msg = emailTemplate.getBodytext();

                        String mail_to1[] = email_id.split(",");

                        for (int ml = 0; ml < mail_to1.length; ml++) {
                            String mail_to = mail_to1[ml];

                            subject = subject.replaceAll("\\{location\\}", location.toUpperCase());

                            msg = msg.replaceAll("\\{tender_title\\}", title.toUpperCase());
                            msg = msg.replaceAll("\\{ref_no\\}", ref_no);
                            msg = msg.replaceAll("\\{start_date\\}", announceDate);
                            msg = msg.replaceAll("\\{end_date\\}", submitLastdate2);
                            msg = msg.replaceAll("\\{fee\\}", docCost);
                            msg = msg.replaceAll("\\{vendor_code\\}", vendor_code);
                            msg = msg.replaceAll("\\{location\\}", location.toUpperCase());
                            msg = msg.replaceAll("\\{department\\}", department);

                            SendMail s = new SendMail();
                            s.sendMail("", mail_to, subject, msg);

                        }

                    }
                } catch (Exception e11) {
                }
            }

        }

        //    mv.setViewName("Tender/CreateTender");
        //    return mv;
    }

