            List tenderPreQualification = authTenderPreQualificationService.readByRefNo(refNo);
            String tenderPreQualificationDocument = "";
            String tenderPreQualificationDocumentRemark = "";
            String tenderPreQualificationRemark = "";
            for (Object o : tenderPreQualification) {
                AuthTenderPreQualification tpq = (AuthTenderPreQualification) o;
                tenderPreQualificationDocument = tpq.getDocument();
                tenderPreQualificationDocumentRemark = tpq.getDocumentRemark();
                tenderPreQualificationRemark = tpq.getRemark();
            }

            mv.getModelMap().put("tenderPreQualificationDocument", tenderPreQualificationDocument);
            mv.getModelMap().put("tenderPreQualificationDocumentRemark", tenderPreQualificationDocumentRemark);
            mv.getModelMap().put("tenderPreQualificationRemark", tenderPreQualificationRemark);

            List tenderTechnical = authTenderTechnicalService.readByRefNo(refNo);
            String tenderTechnicalDoc = "";
            String tenderTechnicalDocRemark = "";
            String tenderTermsConditionDoc = "";
            String tenderTermsConditionRemark = "";
            String tenderTechnicalDocument = "";
            String tenderTechnicalDocumentRemark = "";
            String tenderTechnicalRemark = "";
            for (Object o : tenderTechnical) {
                AuthTenderTechnical tt = (AuthTenderTechnical) o;
                tenderTechnicalDoc = tt.getTechnicalDoc();
                tenderTechnicalDocRemark = tt.getTechnicalRemark();
                tenderTermsConditionDoc = tt.getTermsConditionDoc();
                tenderTermsConditionRemark = tt.getTermsConditionRemark();
                tenderTechnicalDocument = tt.getDocument();
                tenderTechnicalDocumentRemark = tt.getDocumentRemark();
                tenderTechnicalRemark = tt.getRemark();
            }

            mv.getModelMap().put("id", id);
            mv.getModelMap().put("tenderTechnicalDoc", tenderTechnicalDoc);
            mv.getModelMap().put("tenderTechnicalDocRemark", tenderTechnicalDocRemark);
            mv.getModelMap().put("tenderTermsConditionDoc", tenderTermsConditionDoc);
            mv.getModelMap().put("tenderTermsConditionDoc", tenderTermsConditionDoc);
            mv.getModelMap().put("tenderTermsConditionRemark", tenderTermsConditionRemark);
            mv.getModelMap().put("tenderTechnicalDocument", tenderTechnicalDocument);
            mv.getModelMap().put("tenderTechnicalRemark", tenderTechnicalRemark);

            mv.getModelMap().put("tenderItemMaster", tenderItemMaster);
            mv.getModelMap().put("tenderVendor", tenderVendor);

            mv.getModelMap().put("tenderPreQualification", tenderPreQualification);
            mv.getModelMap().put("tenderTechnical", tenderTechnical);

            mv.getModelMap().put("tenderMaster", authTenderMaster);
            mv.getModelMap().put("tender_remark", tender_remark);
            mv.getModelMap().put("refNo", refNo);

            mv.getModelMap().put("generalDocs", generalDocs);
