    public ModelAndView activityLogsPaginationAjax(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String loginUserName = user.getUserFullName();

        int draw = Integer.parseInt(request.getParameter("draw"));
        int start = Integer.parseInt(request.getParameter("start"));
        int length = Integer.parseInt(request.getParameter("length"));

        String searchValue = request.getParameter("searchValue");

        String userName = request.getParameter("userName");
        String fromDate = request.getParameter("fromdate");
        String toDate = request.getParameter("todate");

        String orderColumnIndex = request.getParameter("order[0][column]");
        String orderDir = request.getParameter("order[0][dir]");

        if (userName == null || userName.equals("")) {
            userName = loginUserName;
        }

        if (orderDir == null || orderDir.equals("")) {
            orderDir = "desc";
        }

        if (orderColumnIndex == null || orderColumnIndex.equals("")) {
            orderColumnIndex = "0";
        }

        String orderColumn = "srNoValue";

        if (orderColumnIndex != null) {

            switch (Integer.parseInt(orderColumnIndex)) {

                case 0:
                    orderColumn = "srNoValue";
                    break;
                case 1:
                    orderColumn = "userName";
                    break;
                case 2:
                    orderColumn = "action";
                    break;
                case 4:
                    orderColumn = "ip";
                    break;
                default:
                    orderColumn = "srNoValue";
            }
        }

        List list = logService.getActivityLogsPagination(start, length, searchValue, userName, fromDate, toDate, orderColumn, orderDir);

        int recordsTotal = logService.getActivityLogsCount(userName);

        int recordsFiltered = logService.getFilteredActivityLogsCount(searchValue, userName, fromDate, toDate);

        JSONArray dataArray = new JSONArray();

        boolean isAsc = "asc".equalsIgnoreCase(orderDir);

        int srNo;

        if (isAsc) {
            srNo = recordsFiltered - start;
        } else {
            srNo = start + 1;
        }

        for (Object obj : list) {

            LogsMaster logsMaster = (LogsMaster) obj;

            JSONObject json = new JSONObject();

            String lDate = "";
            if (logsMaster.getlDate() != null) {
                try {
                    SimpleDateFormat inputFormat = new SimpleDateFormat("yyyy-MM-dd");
                    SimpleDateFormat outputFormat = new SimpleDateFormat("dd-MM-yyyy");
                    lDate = outputFormat.format(inputFormat.parse(logsMaster.getlDate()));
                } catch (Exception e) {
                    lDate = logsMaster.getlDate();
                }
            }

            String time = logsMaster.getTime() != null ? logsMaster.getTime() : "";

            if (isAsc) {
                json.put("srNo", srNo--);
            } else {
                json.put("srNo", srNo++);
            }

            json.put("userName", logsMaster.getUserName() != null ? logsMaster.getUserName() : "");
            json.put("activity", logsMaster.getAction() != null ? logsMaster.getAction() : "");
            json.put("dateTime", lDate + " " + time);
            json.put("ipAddress", logsMaster.getIp() != null ? logsMaster.getIp() : "");

            dataArray.put(json);
        }

        JSONObject responseJson = new JSONObject();

        responseJson.put("draw", draw);

        responseJson.put("recordsTotal", recordsTotal);

        responseJson.put("recordsFiltered", recordsFiltered);

        responseJson.put("data", dataArray);

        response.setContentType("application/json");
        response.setCharacterEncoding("UTF-8");

        response.getWriter().write(responseJson.toString());

        return null;

    }

    public void activityLogsReportExportExcel(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Session expired");
            return;
        }
        UserMaster user = (UserMaster) session.getAttribute("user");
        String loginUserName = user.getUserFullName();

        String searchValue = request.getParameter("searchValue");

        String userName = request.getParameter("userName");
        String fromDate = request.getParameter("fromdate");
        String toDate = request.getParameter("todate");

        String orderColumn = "srNoValue";
        String orderDir = "asc";

        if (userName == null || userName.equals("")) {
            userName = loginUserName;
        }

        int start = 0;
        int filteredRecords = logService.getFilteredActivityLogsCount(searchValue, userName, fromDate, toDate);

        List activityLogsReportList = logService.getActivityLogsPagination(start, filteredRecords, searchValue, userName, fromDate, toDate, orderColumn, orderDir);

        Workbook workbook = new XSSFWorkbook();
        Sheet sheet = workbook.createSheet("Activity Logs Report");

        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBoldweight(Font.BOLDWEIGHT_BOLD);
        headerFont.setColor(IndexedColors.WHITE.getIndex());
        headerStyle.setFont(headerFont);
        headerStyle.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        XSSFColor headerColor = new XSSFColor(new java.awt.Color(31, 78, 120));
        ((XSSFCellStyle) headerStyle).setFillForegroundColor(headerColor);
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);

        CellStyle wrapStyle = workbook.createCellStyle();
        wrapStyle.setWrapText(true);
        wrapStyle.setVerticalAlignment(CellStyle.VERTICAL_TOP);

        String[] headers = {
            "Sr.No.", "User Name", "Activity", "Date Time", "IP"
        };

        int rowNum = 0;
        int srNo = 1;

        Row headerRow = sheet.createRow(rowNum++);
        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        sheet.createFreezePane(0, 1);

        if (activityLogsReportList != null) {

            for (Object obj : activityLogsReportList) {

                LogsMaster logs = (LogsMaster) obj;

                String lDate = "";
                if (logs.getlDate() != null) {
                    try {
                        SimpleDateFormat inputFormat = new SimpleDateFormat("yyyy-MM-dd");
                        SimpleDateFormat outputFormat = new SimpleDateFormat("dd-MM-yyyy");
                        lDate = outputFormat.format(inputFormat.parse(logs.getlDate()));
                    } catch (Exception e) {
                        lDate = logs.getlDate();
                    }
                }

                String time = logs.getTime() != null ? logs.getTime() : "";

                Row excelRow = sheet.createRow(rowNum++);
                excelRow.createCell(0).setCellValue(srNo++);
                excelRow.createCell(1).setCellValue(logs.getUserName() != null ? logs.getUserName() : "");
                excelRow.createCell(2).setCellValue(logs.getAction() != null ? logs.getAction() : "");
                excelRow.createCell(3).setCellValue(lDate + " " + time);
                excelRow.createCell(4).setCellValue(logs.getIp() != null ? logs.getIp() : "");

            }
        }

        for (int i = 0; i < headers.length; i++) {
            sheet.autoSizeColumn(i);
        }

        SimpleDateFormat fileDateFormat = new SimpleDateFormat("ddMMyyyy");
        String fileDate = fileDateFormat.format(new Date());
        String fileName = "Activity_Logs_Report_" + fileDate + ".xlsx";

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        OutputStream outputStream = response.getOutputStream();
        try {
            workbook.write(outputStream);
        } finally {
            outputStream.flush();
            outputStream.close();
        }
    }

    public ModelAndView tenderReport(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();
        String ref_no = request.getParameter("refNo");
        String vendor_code = request.getParameter("vendorCode");
        String tender_no = "";
        String tender_title = "";
        String open_from_date = request.getParameter("open_from_date");
        String open_to_date = request.getParameter("open_to_date");
        String close_from_date = "";
        String close_to_date = "";
        String day = request.getParameter("day");
        if (day == null) {
            day = "1";
        }

        SimpleDateFormat sdf11 = new SimpleDateFormat("dd-MM-yyyy");
        Date date11 = new java.util.Date();
        String sysdate11 = sdf11.format(date11);

        if (day.equals("7")) {
            DateFormat dateFormat = new SimpleDateFormat("dd-MM-yyyy");
            Calendar cal = Calendar.getInstance();
            cal.add(Calendar.DATE, -7);
            Date todate1 = cal.getTime();
            String fromdate = dateFormat.format(todate1);
            open_from_date = fromdate;
        } else if (day.equals("15")) {
            DateFormat dateFormat = new SimpleDateFormat("dd-MM-yyyy");
            Calendar cal = Calendar.getInstance();
            cal.add(Calendar.DATE, -15);
            Date todate1 = cal.getTime();
            String fromdate = dateFormat.format(todate1);
            open_from_date = fromdate;
        } else if (day.equals("30")) {
            DateFormat dateFormat = new SimpleDateFormat("dd-MM-yyyy");
            Calendar cal = Calendar.getInstance();
            cal.add(Calendar.DATE, -30);
            Date todate1 = cal.getTime();
            String fromdate = dateFormat.format(todate1);
            open_from_date = fromdate;
        } else if (day.equals("1")) {
            open_from_date = sysdate11;
        } else {
            open_from_date = sysdate11;
        }

        open_to_date = sysdate11;

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String location = employeeMaster.getLocation();
        String department = employeeMaster.getDepartment();

        mv.getModelMap().put("day", day);
        mv.getModelMap().put("tender_no", tender_no);
        mv.getModelMap().put("tender_title", tender_title);
        mv.getModelMap().put("open_from_date", open_from_date);
        mv.getModelMap().put("open_to_date", open_to_date);
        mv.getModelMap().put("close_from_date", close_from_date);
        mv.getModelMap().put("close_to_date", close_to_date);

        UserRights userRights = userRightsService.readByUser(username);

        List list = tenderMasterService.tenderReportList(location, department, tender_no, tender_title, open_from_date, open_to_date, close_from_date, close_to_date);

        ArrayList<TenderStatus> bs = new ArrayList<TenderStatus>();

        String refNo = "";
        int tenderPhase = 0;
        String title = "";
        int id = 0;
        String pr_no = "";
        String tender_date = "";
        String tender_due_date = "";
        String emd = "";
        String created_by = "";
        for (Object o : list) {
            TenderMaster tm = (TenderMaster) o;
            id = tm.getId();
            refNo = tm.getRefNo();
            tenderPhase = tm.getTenderPhase();
            title = tm.getTitle();
            pr_no = tm.getPrNo();
            tender_date = tm.getAnnounceDate();
            tender_due_date = tm.getSubmitLastdate();

            String bid_status = "0";
            SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
            SimpleDateFormat sdf1 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
            SimpleDateFormat sdf2 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            Date sysdate1 = (Date) sdf.parse(tender_due_date);
            String sysdate = sdf1.format(sysdate1);
            Date submitdate = (Date) sdf1.parse(sysdate);

            Date sysdate12 = (Date) sdf.parse(tender_due_date);
            String sysdate122 = sdf2.format(sysdate12);
            Date submitdate2 = (Date) sdf2.parse(sysdate122);

            String currentdate = "";
            Date date = new java.util.Date();
            currentdate = sdf2.format(date);
            date = (Date) sdf2.parse(currentdate);

            if (submitdate2.before(date) && !submitdate2.equals(date)) {
                bid_status = "1";
            }
            emd = tm.getEmd();
            created_by = tm.getContactPerson();

            List list1 = tenderVendorService.vendorList(refNo);

            int vendor_total = 0;
            for (Object o1 : list1) {
                vendor_total++;
            }

            int total_bid = 0;
            String price_bid_open_flag = "";
            List list2 = vendorTenderBidService.vendorList(refNo);
            for (Object o1 : list2) {
                total_bid++;
                VendorTenderBid vtb = (VendorTenderBid) o1;
                String bidopen = vtb.getBidOpenFlag();
                if (bidopen == null) {
                    bidopen = "";
                }
                if (bidopen.equals("1")) {
                    price_bid_open_flag = "1";
                }
            }

            String L1_price = "";
            if (price_bid_open_flag.equals("1")) {
                List list11 = vendorTenderBidService.vendorL1List(refNo);

                for (Object o1 : list11) {
                    VendorTenderBid vtb = (VendorTenderBid) o1;
                    L1_price = vtb.getGrandTotal();
                }
            }

            int total_regret = 0;
            List list3 = tenderRegretService.regretList(refNo);
            if (list3.isEmpty()) {
            } else {
                for (Object o1 : list3) {
                    total_regret++;
                }
            }

            int status = 0;
            String pre_bid_open_flag = "0";
            String pre_bid_approve_flag = "0";
            if (tenderPhase == 3) {
                List list4 = vendorPreBidService.vendorList(refNo);
                for (Object o1 : list4) {
                    VendorPreBid vpb = (VendorPreBid) o1;
                    String prebidopen = vpb.getBidOpenFlag();
                    if (prebidopen == null) {
                        prebidopen = "0";
                    }
                    if (prebidopen.equals("1")) {
                        pre_bid_open_flag = "1";
                    }
                    String prebidapprove = vpb.getBidApproveFlag();
                    if (prebidapprove == null) {
                        prebidapprove = "0";
                    }
                    if (prebidapprove.equals("1")) {
                        pre_bid_approve_flag = "1";
                    }
                }
            }
            String tech_bid_open_flag = "0";
            String tech_bid_approve_flag = "0";
            if (tenderPhase == 2 || tenderPhase == 3) {
                List list5 = vendorTechnicalBidService.vendorList(refNo);
                for (Object o1 : list5) {
                    VendorTechnicalBid vtb = (VendorTechnicalBid) o1;
                    String techbidopen = vtb.getBidOpenFlag();
                    if (techbidopen == null) {
                        techbidopen = "0";
                    }
                    if (techbidopen.equals("1")) {
                        tech_bid_open_flag = "1";
                    }
                    String techbidapprove = vtb.getBidApproveFlag();
                    if (techbidapprove == null) {
                        techbidapprove = "0";
                    }
                    if (techbidapprove.equals("1")) {
                        tech_bid_approve_flag = "1";
                    }
                }
            }
            if (tenderPhase == 1) {

            }

            int auth = tm.getAuthorizeFlag();
            if (auth == 0) {
                bid_status = "AUTHORIZE PENDING";
            } else {
                int bid_open_flag = tm.getOpenBidFlag();
                if (bid_open_flag == 1) {
                    bid_status = "CLOSE - Final Bid Open";
                } else {
                    if (submitdate2.after(date)) {
                        bid_status = "LIVE";
                    } else if (submitdate2.before(date)) {
                        bid_status = "CLOSE";
                    }
                }
            }

            TenderStatus bidStatus1 = new TenderStatus(1, refNo, id, title, pr_no, tender_date, tender_due_date, emd, created_by, tenderPhase, vendor_total, total_bid, total_regret, pre_bid_open_flag, pre_bid_approve_flag, tech_bid_open_flag, tech_bid_approve_flag, price_bid_open_flag, bid_status, L1_price);
            bs.add(bidStatus1);
        }

        request.setAttribute("list", list);
        mv.getModelMap().put("bs", bs);

        mv.getModelMap().put("list", list);
        mv.getModelMap().put("tenderMaster", tenderMaster);

        mv.setViewName("Tender/TenderReport");
        return mv;
    }

    public ModelAndView tenderReportPaginationAjax(HttpServletRequest request, HttpServletResponse response) throws Exception {

        try {
            int draw = Integer.parseInt(request.getParameter("draw") != null ? request.getParameter("draw") : "1");
            int start = Integer.parseInt(request.getParameter("start") != null ? request.getParameter("start") : "0");
            int length = Integer.parseInt(request.getParameter("length") != null ? request.getParameter("length") : "10");

            String searchValue = request.getParameter("searchValue") != null ? request.getParameter("searchValue") : "";
            String tenderNo = request.getParameter("tenderNo") != null ? request.getParameter("tenderNo") : "";
            String projectName = request.getParameter("projectName") != null ? request.getParameter("projectName") : "";
            String openFromDate = request.getParameter("openFromDate") != null ? request.getParameter("openFromDate") : "";
            String openToDate = request.getParameter("openToDate") != null ? request.getParameter("openToDate") : "";
            String closeFromDate = request.getParameter("closeFromDate") != null ? request.getParameter("closeFromDate") : "";
            String closeToDate = request.getParameter("closeToDate") != null ? request.getParameter("closeToDate") : "";
            String lastDays = request.getParameter("lastDays") != null ? request.getParameter("lastDays") : "1";

            String orderColumnIndex = request.getParameter("order[0][column]") != null ? request.getParameter("order[0][column]") : "0";
            String orderDir = request.getParameter("order[0][dir]") != null ? request.getParameter("order[0][dir]") : "desc";

            SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy");
            String sysdate = sdf.format(new java.util.Date());

            boolean hasManualFilters = !tenderNo.isEmpty()
                    || !projectName.isEmpty()
                    || !searchValue.isEmpty()
                    || !openFromDate.isEmpty()
                    || !openToDate.isEmpty()
                    || !closeFromDate.isEmpty()
                    || !closeToDate.isEmpty();

            if (!hasManualFilters) {
                Calendar cal = Calendar.getInstance();

                if (lastDays.equals("7") || lastDays.equals("15") || lastDays.equals("30")) {
                    cal.add(Calendar.DATE, -Integer.parseInt(lastDays));
                    openFromDate = sdf.format(cal.getTime());
                } else {
                    openFromDate = sysdate;
                }
                openToDate = sysdate;

            } else if (openFromDate.isEmpty() && !openToDate.isEmpty()) {
                openFromDate = "";
            } else if (!openFromDate.isEmpty() && openToDate.isEmpty()) {
                openToDate = sysdate;
            }

            HttpSession session = request.getSession(false);
            UserMaster user = (UserMaster) session.getAttribute("user");
            String username = user.getLoginName();
            EmployeeMaster employeeMaster = employeeMasterService.read(username);
            String location = employeeMaster.getLocation();
            String department = employeeMaster.getDepartment();

            String orderColumn;
            switch (Integer.parseInt(orderColumnIndex)) {
                case 1:
                    orderColumn = "refNo";
                    break;
                case 2:
                    orderColumn = "title";
                    break;
                case 3:
                    orderColumn = "prNo";
                    break;
                case 4:
                    orderColumn = "announceDate";
                    break;
                case 5:
                    orderColumn = "submitLastdate";
                    break;
                case 6:
                    orderColumn = "emd";
                    break;
                default:
                    orderColumn = "id";
                    break;
            }

            List list = tenderMasterService.tenderReportPaginationList(location, department, tenderNo, projectName, openFromDate, openToDate, closeFromDate, closeToDate, start, length, searchValue, orderColumn, orderDir);
            int recordsTotal = tenderMasterService.tenderReportCount(location, department);
            int recordsFiltered = tenderMasterService.tenderReportFilteredCount(location, department, tenderNo, projectName, openFromDate, openToDate, closeFromDate, closeToDate, searchValue);

            JSONArray dataArray = new JSONArray();
            boolean isAsc = "asc".equalsIgnoreCase(orderDir);
            int srNo = isAsc ? (recordsFiltered - start) : (start + 1);

            SimpleDateFormat dtFmt = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            for (Object o : list) {
                TenderMaster tm = (TenderMaster) o;

                String refNo = tm.getRefNo() != null ? tm.getRefNo() : "";
                int tenderPhase = tm.getTenderPhase();
                String title = tm.getTitle() != null ? tm.getTitle() : "";
                String pr_no = tm.getPrNo() != null ? tm.getPrNo() : "";
                String tender_date = tm.getAnnounceDate() != null ? tm.getAnnounceDate() : "";
                String tender_due_date = tm.getSubmitLastdate() != null ? tm.getSubmitLastdate() : "";
                String emd = tm.getEmd() != null ? tm.getEmd() : "";
                String created_by = tm.getContactPerson() != null ? tm.getContactPerson() : "";

                String bid_status = "CLOSE";
                try {
                    Date submitDate = dtFmt.parse(tender_due_date);
                    Date currentDate = dtFmt.parse(dtFmt.format(new java.util.Date()));

                    if (tm.getAuthorizeFlag() == 0) {
                        bid_status = "AUTHORIZE PENDING";
                    } else if (tm.getOpenBidFlag() == 1) {
                        bid_status = "CLOSE - Final Bid Open";
                    } else if (submitDate.after(currentDate)) {
                        bid_status = "LIVE";
                    } else {
                        bid_status = "CLOSE";
                    }
                } catch (Exception e) {
                    bid_status = "CLOSE";
                }

                int vendor_total = tenderVendorService.vendorList(refNo).size();

                int total_bid = 0;
                String price_bid_open_flag = "";
                List bidList = vendorTenderBidService.vendorList(refNo);
                for (Object o1 : bidList) {
                    total_bid++;
                    VendorTenderBid vtb = (VendorTenderBid) o1;
                    String bidopen = vtb.getBidOpenFlag();
                    if ("1".equals(bidopen)) {
                        price_bid_open_flag = "1";
                    }
                }

                String L1_price = "";
                if ("1".equals(price_bid_open_flag)) {
                    List l1List = vendorTenderBidService.vendorL1List(refNo);
                    if (!l1List.isEmpty()) {
                        L1_price = ((VendorTenderBid) l1List.get(0)).getGrandTotal();
                    }
                }

                int total_regret = tenderRegretService.regretList(refNo).size();

                JSONObject json = new JSONObject();
                json.put("srNo", isAsc ? srNo-- : srNo++);
                json.put("refNo", refNo);
                json.put("id", tm.getId());
                json.put("title", title);
                json.put("prNo", pr_no);
                json.put("tenderDate", tender_date);
                json.put("tenderDueDate", tender_due_date);
                json.put("emd", emd);
                json.put("createdBy", created_by);
                json.put("tenderPhase", tenderPhase);
                json.put("vendorTotal", vendor_total);
                json.put("totalBid", total_bid);
                json.put("totalRegret", total_regret);
                json.put("priceBidOpenFlag", price_bid_open_flag);
                json.put("bidStatus", bid_status);
                json.put("l1Price", L1_price);

                dataArray.put(json);
            }

            JSONObject responseJson = new JSONObject();
            responseJson.put("draw", draw);
            responseJson.put("recordsTotal", recordsTotal);
            responseJson.put("recordsFiltered", recordsFiltered);
            responseJson.put("data", dataArray);

            response.setContentType("application/json");
            response.setCharacterEncoding("UTF-8");
            response.getWriter().write(responseJson.toString());

        } catch (Exception e) {
            e.printStackTrace();
            JSONObject errorJson = new JSONObject();
            errorJson.put("draw", 1);
            errorJson.put("recordsTotal", 0);
            errorJson.put("recordsFiltered", 0);
            errorJson.put("data", new JSONArray());
            errorJson.put("error", e.getMessage());

            response.setContentType("application/json");
            response.setCharacterEncoding("UTF-8");
            response.getWriter().write(errorJson.toString());
        }

        return null;

    }

    public void tenderReportExportExcel(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Session expired");
            return;
        }
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        String searchValue = request.getParameter("searchValue") != null ? request.getParameter("searchValue") : "";
        String tenderNo = request.getParameter("tenderNo") != null ? request.getParameter("tenderNo") : "";
        String projectName = request.getParameter("projectName") != null ? request.getParameter("projectName") : "";
        String openFromDate = request.getParameter("openFromDate") != null ? request.getParameter("openFromDate") : "";
        String openToDate = request.getParameter("openToDate") != null ? request.getParameter("openToDate") : "";
        String closeFromDate = request.getParameter("closeFromDate") != null ? request.getParameter("closeFromDate") : "";
        String closeToDate = request.getParameter("closeToDate") != null ? request.getParameter("closeToDate") : "";
        String lastDays = request.getParameter("lastDays") != null ? request.getParameter("lastDays") : "1";

        SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy");
        String sysdate = sdf.format(new java.util.Date());

        boolean hasManualFilters = !tenderNo.isEmpty()
                || !projectName.isEmpty()
                || !searchValue.isEmpty()
                || !openFromDate.isEmpty()
                || !openToDate.isEmpty()
                || !closeFromDate.isEmpty()
                || !closeToDate.isEmpty();

        if (!hasManualFilters) {
            Calendar cal = Calendar.getInstance();

            if (lastDays.equals("7") || lastDays.equals("15") || lastDays.equals("30")) {
                cal.add(Calendar.DATE, -Integer.parseInt(lastDays));
                openFromDate = sdf.format(cal.getTime());
            } else {
                openFromDate = sysdate;
            }
            openToDate = sysdate;

        } else if (openFromDate.isEmpty() && !openToDate.isEmpty()) {
            openFromDate = "";
        } else if (!openFromDate.isEmpty() && openToDate.isEmpty()) {
            openToDate = sysdate;
        }

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String location = employeeMaster.getLocation();
        String department = employeeMaster.getDepartment();

        String orderColumn = "id";
        String orderDir = "desc";

        int start = 0;
        int filteredRecords = tenderMasterService.tenderReportFilteredCount(location, department, tenderNo, projectName, openFromDate, openToDate, closeFromDate, closeToDate, searchValue);

        List tenderReportList = tenderMasterService.tenderReportPaginationList(location, department, tenderNo, projectName, openFromDate, openToDate, closeFromDate, closeToDate, start, filteredRecords, searchValue, orderColumn, orderDir);

        Workbook workbook = new XSSFWorkbook();
        Sheet sheet = workbook.createSheet("Tender Report");

        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBoldweight(Font.BOLDWEIGHT_BOLD);
        headerFont.setColor(IndexedColors.WHITE.getIndex());
        headerStyle.setFont(headerFont);
        headerStyle.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);
        headerStyle.setAlignment(CellStyle.ALIGN_CENTER);
        headerStyle.setVerticalAlignment(CellStyle.VERTICAL_CENTER);

        XSSFColor headerColor = new XSSFColor(new java.awt.Color(31, 78, 120));
        ((XSSFCellStyle) headerStyle).setFillForegroundColor(headerColor);
        headerStyle.setFillPattern(CellStyle.SOLID_FOREGROUND);

        CellStyle wrapStyle = workbook.createCellStyle();
        wrapStyle.setWrapText(true);
        wrapStyle.setVerticalAlignment(CellStyle.VERTICAL_TOP);

        String[] headers = {
            "Sr.No.", "Tender No.", "Project Name", "Tender Start Date", "Tender End Date",
            "EMD", "Created By", "Tender Type", "Bid Sent To No. Of Vendor",
            "Bid Received/Regret From No. Of Vendor", "Bid Status"
        };

        int rowNum = 0;
        int srNo = 1;

        Row headerRow = sheet.createRow(rowNum++);
        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        sheet.createFreezePane(0, 1);

        SimpleDateFormat dtFmt = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

        if (tenderReportList != null) {

            for (Object o : tenderReportList) {

                TenderMaster tm = (TenderMaster) o;

                String refNo = tm.getRefNo() != null ? tm.getRefNo() : "";
                int tenderPhase = tm.getTenderPhase();
                String title = tm.getTitle() != null ? tm.getTitle() : "";
                String tenderDate = tm.getAnnounceDate() != null ? tm.getAnnounceDate() : "";
                String tenderDueDate = tm.getSubmitLastdate() != null ? tm.getSubmitLastdate() : "";
                String emd = tm.getEmd() != null ? tm.getEmd() : "";
                String createdBy = tm.getContactPerson() != null ? tm.getContactPerson() : "";

                String bidStatus = "CLOSE";
                try {
                    Date submitDate = dtFmt.parse(tenderDueDate);
                    Date currentDate = dtFmt.parse(dtFmt.format(new java.util.Date()));

                    if (tm.getAuthorizeFlag() == 0) {
                        bidStatus = "AUTHORIZE PENDING";
                    } else if (tm.getOpenBidFlag() == 1) {
                        bidStatus = "CLOSE - Final Bid Open";
                    } else if (submitDate.after(currentDate)) {
                        bidStatus = "LIVE";
                    } else {
                        bidStatus = "CLOSE";
                    }
                } catch (Exception e) {
                    bidStatus = "CLOSE";
                }

                int vendorTotal = 0;
                List vendorList = tenderVendorService.vendorList(refNo);
                if (vendorList != null) {
                    vendorTotal = vendorList.size();
                }

                int totalBid = 0;
                List bidList = vendorTenderBidService.vendorList(refNo);
                if (bidList != null) {
                    totalBid = bidList.size();
                }

                int totalRegret = 0;
                List regretList = tenderRegretService.regretList(refNo);
                if (regretList != null) {
                    totalRegret = regretList.size();
                }

                String bidReceived = totalBid + "/" + totalRegret;

                Row excelRow = sheet.createRow(rowNum++);
                excelRow.createCell(0).setCellValue(srNo++);
                excelRow.createCell(1).setCellValue(refNo);
                excelRow.createCell(2).setCellValue(title);
                excelRow.createCell(3).setCellValue(tenderDate);
                excelRow.createCell(4).setCellValue(tenderDueDate);
                excelRow.createCell(5).setCellValue(emd);
                excelRow.createCell(6).setCellValue(createdBy);
                excelRow.createCell(7).setCellValue(tenderPhase + " Part");
                excelRow.createCell(8).setCellValue(vendorTotal);
                excelRow.createCell(9).setCellValue(bidReceived);
                excelRow.createCell(10).setCellValue(bidStatus);
            }
        }

        for (int i = 0; i < headers.length; i++) {
            sheet.autoSizeColumn(i);
        }

        SimpleDateFormat fileDateFormat = new SimpleDateFormat("ddMMyyyy");
        String fileDate = fileDateFormat.format(new Date());
        String fileName = "Tender_Report_" + fileDate + ".xlsx";

        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        OutputStream outputStream = response.getOutputStream();
        try {
            workbook.write(outputStream);
        } finally {
            outputStream.flush();
            outputStream.close();
        }
    }

