    public ModelAndView vendorReviseBid(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String id = request.getParameter("id");
        String datetime = request.getParameter("submitLastdate");
        String remark = request.getParameter("remark");
        TenderMaster tenderMaster = tenderMasterService.readById(Integer.parseInt(id));

        String refNo = tenderMaster.getRefNo();
        String tender_department = tenderMaster.getDepartment();

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String location = employeeMaster.getLocation();
        String user_department1 = employeeMaster.getDepartment();

        String[] checkId = request.getParameterValues("checkedId");
        String vendor_list = "";
        for (String checkedValues : checkId) {
            vendor_list = vendor_list + "" + checkedValues + ":";
            vendorTenderBidService.updateReviseDate(refNo, checkedValues, datetime, remark);

            String subject = "";
            String msg = "";
            String mail_from = "";
            String mail_to = "";

            TenderVendor tenderVendor = tenderVendorService.readByRefVendor1(refNo, checkedValues);
            mail_to = tenderVendor.getEmailId();
            EmailTemplate emailTemplate = emailTemplateService.readById(17);

            subject = emailTemplate.getSubject();
            msg = emailTemplate.getBodytext();

            msg = msg.replaceAll("\\{tender_title\\}", tenderMaster.getTitle().toUpperCase());
            msg = msg.replaceAll("\\{ref_no\\}", refNo);
            msg = msg.replaceAll("\\{start_date\\}", tenderMaster.getAnnounceDate());
            msg = msg.replaceAll("\\{end_date\\}", datetime);
            msg = msg.replaceAll("\\{vendor_code\\}", checkedValues);
            msg = msg.replaceAll("\\{location\\}", location.toUpperCase());
            msg = msg.replaceAll("\\{department\\}", tender_department);
            msg = msg.replaceAll("\\{remark\\}", remark);

            SendMail s = new SendMail();
            s.sendMail(mail_from, mail_to, subject, msg);
        }

        session.setAttribute("successMessage",
                "Information: Revise Tender Submited successfully");

        mv.getModelMap().put("refNo", refNo);
        mv.getModelMap().put("id", id);
        mv.getModelMap().put("vendor_list", vendor_list);
        mv.getModelMap().put("username", username);
        mv.getModelMap().put("tenderMaster", tenderMaster);
        //mv.setViewName("Tender/PreBidOpenUserView");
        mv.setViewName("redirect:tenderMaster.htm?act=vendorListView&id=" + id);
        return mv;
    }

