    public ModelAndView approveBid(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String id = request.getParameter("id");
        String comment = request.getParameter("comment");

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        TenderPriceApproval tenderPriceApproval = tenderPriceApprovalService.readById(Integer.parseInt(id));
        TenderPriceApprovalUser tenderPriceApprovalUser = tenderPriceApprovalUserService.approvaList2(Integer.parseInt(id));

        int approveId = tenderPriceApproval.getId();
        TenderPriceApprovalComment tenderPriceApprovalComment = tenderPriceApprovalCommentService.readByApproveId(approveId);

        int totalApproval = tenderPriceApproval.getTotalApproval();
        int ca = tenderPriceApproval.getCurrentApproval();

        int level = 0;
        if (totalApproval == ca) {
            tenderPriceApproval.setApprovalStatus(1);
            tenderPriceApprovalUser.setApprovalStatus(1);
            tenderPriceApprovalComment.setApprovalStatus(1);

            String tender_no = tenderPriceApproval.getTenderNo();
            TenderMaster tenderMaster = tenderMasterService.readRefNo(tender_no);
            String user_to = tenderMaster.getTenderAdmin();
            tenderMaster.setOpenBidStatus(1);
            tenderMasterService.update(tenderMaster);
            EmployeeMaster employeeMaster1 = employeeMasterService.read(user_to);
            String email_to = employeeMaster1.getEmailId();

            String subject = "";
            String msg = "";
            String mail_from = "";
            String mail_to = email_to;

            EmailTemplate emailTemplate = emailTemplateService.readById(14);

            subject = emailTemplate.getSubject();
            msg = emailTemplate.getBodytext();

            msg = msg.replaceAll("\\{tender_title\\}", tenderMaster.getTitle().toUpperCase());
            msg = msg.replaceAll("\\{ref_no\\}", tenderMaster.getRefNo());

            SendMail s = new SendMail();
            s.sendMail(mail_from, mail_to, subject, msg);

        } else {

            level = tenderPriceApprovalUser.getLevel();
            level++;

            tenderPriceApproval.setCurrentApproval(level);
            tenderPriceApprovalUser.setApprovalStatus(1);
            tenderPriceApprovalComment.setApprovalStatus(1);

            mv.getModelMap().put("tenderPriceApprovalUser", tenderPriceApprovalUser);

            String tender_no = tenderPriceApproval.getTenderNo();
            TenderMaster tenderMaster = tenderMasterService.readRefNo(tender_no);
            TenderPriceApprovalUser tenderPriceApprovalUser1 = tenderPriceApprovalUserService.readByLevel(tender_no, level);

            String user_to = tenderPriceApprovalUser1.getUserId();
            EmployeeMaster employeeMaster1 = employeeMasterService.read(user_to);
            String email_to = employeeMaster1.getEmailId();

            String subject = "";
            String msg = "";
            String mail_from = "";
            String mail_to = email_to;

            EmailTemplate emailTemplate = emailTemplateService.readById(13);

            subject = emailTemplate.getSubject();
            msg = emailTemplate.getBodytext();

            msg = msg.replaceAll("\\{tender_title\\}", tenderMaster.getTitle().toUpperCase());
            msg = msg.replaceAll("\\{ref_no\\}", tenderMaster.getRefNo());

            SendMail s = new SendMail();
            s.sendMail(mail_from, mail_to, subject, msg);
        }

        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String formattedDate = myDateObj.format(myFormatObj);
        tenderPriceApprovalComment.setDateTime(formattedDate);

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String employeeCode = employeeMaster.getEmployeeCode();
        tenderPriceApprovalComment.setUserId(employeeCode);
        tenderPriceApprovalComment.setTenderApprovalId(approveId);

        tenderPriceApprovalComment.setApprovalComment(comment);
        tenderPriceApprovalCommentService.create(tenderPriceApprovalComment);
        tenderPriceApprovalService.update(tenderPriceApproval);
        tenderPriceApprovalUserService.update(tenderPriceApprovalUser);

        int total_level = tenderPriceApprovalUser.getLevel();

        List tenderPriceApprovalUser1 = tenderPriceApprovalUserService.readByRefNo(Integer.parseInt(id));

        request.setAttribute("successMessage",
                "Information: Tender Approve successfully");

        mv.getModelMap().put("tenderPriceApproval", tenderPriceApproval);
        mv.setViewName("forward:tenderMaster.htm?act=approvePriceBid");
        return mv;
    }

