    public ModelAndView addPoNumber(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        String id = request.getParameter("id");
        String comments = request.getParameter("comments");
        String po_no = request.getParameter("po_no");

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        String generalfile = request.getParameter("generalfile");
        if (generalfile == null) {
            generalfile = "";
        }

        TenderMaster tenderMaster = tenderMasterService.readById(Integer.parseInt(id));
        String refNo = tenderMaster.getRefNo();
        String RefNo = refNo.replace("/", "");

        String path = getServletContext().getRealPath("/")
                + File.separator + "StorageYard" + File.separator + "Tender"
                + File.separator + RefNo;
        File f1 = new File(path);
        boolean bool = f1.mkdir();

        MultipartHttpServletRequest multipartRequest = (MultipartHttpServletRequest) request;

        MultipartFile multipartFile = multipartRequest.getFile("generalfile");
        if (multipartFile != null && multipartFile.getSize() > 0) {
            try {
                String fileLocationURL = getServletContext().getRealPath("/")
                        + File.separator + "StorageYard" + File.separator + "Tender"
                        + File.separator + RefNo + File.separator;
                File photoFile = new File(fileLocationURL + multipartFile.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", ""));
                generalfile = multipartFile.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", "");
                multipartFile.transferTo(photoFile);
                //    vendorInformation.setTermsConditionFile(photoFile+"");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        tenderMaster.setCloseFlag(1);
        tenderMaster.setAuditFlag(0);
        tenderMaster.setComments(comments);
        tenderMaster.setPoNumber(po_no);
        tenderMaster.setAuditFile(generalfile);
        tenderMasterService.update(tenderMaster);

        EmployeeMaster employeeMaster = employeeMasterService.read(username);
        String employeeCode = employeeMaster.getEmployeeCode();

        request.setAttribute("successMessage",
                "Information: Add PO Number successfully");

        // mv.getModelMap().put("tenderPriceApproval", tenderPriceApproval);
        mv.setViewName("forward:tenderMaster.htm?act=approvedTenderList");
        return mv;
    }

