    public ModelAndView uploadFileSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();
        String ref_no = request.getParameter("refNo");

        String vendor_code = request.getParameter("vendorCode");
        String tender_no = request.getParameter("tender_no");

        String vendor_file = request.getParameter("vendor_file");
        if (vendor_file == null) {
            vendor_file = "";
        }

        MultipartHttpServletRequest multipartRequest = (MultipartHttpServletRequest) request;

        MultipartFile multipartFile = multipartRequest.getFile("vendor_file");
        if (multipartFile != null && multipartFile.getSize() > 0) {
            try {
                String fileLocationURL = getServletContext().getRealPath("/")
                        + File.separator + "StorageYard" + File.separator + "Tender"
                        + File.separator;
                File photoFile = new File(fileLocationURL + multipartFile.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", ""));
                vendor_file = multipartFile.getOriginalFilename().replaceAll(" ", "").replaceAll("&", "").replaceAll("\\+", "");
                multipartFile.transferTo(photoFile);
                //    vendorInformation.setTermsConditionFile(photoFile+"");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.setViewName("Tender/UploadFile");
        return mv;
    }

