    public ModelAndView technicalApprovalWorkFlowSubmit(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        TechnicalTenderPriceApproval technicalTenderPriceApproval = new TechnicalTenderPriceApproval();
        TechnicalTenderPriceApprovalUser technicalTenderPriceApprovalUser = new TechnicalTenderPriceApprovalUser();

        LocalDateTime myDateObj = LocalDateTime.now();
        DateTimeFormatter myFormatObj = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
        String formattedDate = myDateObj.format(myFormatObj);

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String username = user.getLoginName();

        UserRights userRights = userRightsService.readByUser(username);
        EmployeeMaster employeeMaster = employeeMasterService.read(username);

        String employeeCode = employeeMaster.getEmployeeCode();

        String id = request.getParameter("id");

        TenderMaster tenderMaster = tenderMasterService.readById(Integer.parseInt(id));
        String refNo = request.getParameter("refNo");

        String vendorCode = request.getParameter("vendorCode");
        if (vendorCode == null) {
            vendorCode = "";
        }

        String comment = request.getParameter("comment");
        if (comment == null) {
            comment = "";
        }

//        List TenderApprovalUser = tenderApprovalUserService.readByIdToList(tenderApprovalSetting);
//        policyCount = TenderApprovalUser.size();
        String tenderApprovalSetting1[] = request.getParameterValues("tenderApprovalSetting1");
        int size = tenderApprovalSetting1.length;

        technicalTenderPriceApproval.setVendorCode(vendorCode);
        technicalTenderPriceApproval.setTenderNo(refNo);
        technicalTenderPriceApproval.setCurrentApproval(1);
        technicalTenderPriceApproval.setApprovalStatus(0);
        technicalTenderPriceApproval.setTotalApproval(size);
        technicalTenderPriceApproval.setDateTime(formattedDate);
        technicalTenderPriceApproval.setApprovalRemark(comment);
        technicalTenderPriceApproval.setUserId(employeeCode);
        technicalTenderPriceApproval.setApprovalRemark(comment);
        technicalTenderPriceApprovalService.create(technicalTenderPriceApproval);

        int TenderApprovalUserId = technicalTenderPriceApproval.getId();
        int approveId = technicalTenderPriceApproval.getId();
        String TenderApprovalUserId1 = Integer.toString(TenderApprovalUserId);

        List TenderApprovalUser = tenderApprovalUserService.readByIdToList(TenderApprovalUserId1);
        int i1 = 0;
        int a = 1;
        for (String s : tenderApprovalSetting1) {
            i1++;
            technicalTenderPriceApprovalUser.setUserId(s);
            technicalTenderPriceApprovalUser.setTenderNo(refNo);
            technicalTenderPriceApprovalUser.setVendorCode(vendorCode);
            technicalTenderPriceApprovalUser.setTenderApprovalId(approveId);
            technicalTenderPriceApprovalUser.setLevel(i1);
            technicalTenderPriceApprovalUser.setApprovalStatus(0);
            technicalTenderPriceApprovalUserService.create(technicalTenderPriceApprovalUser);
            a++;
        }

        mv.getModelMap().put("id", id);

        mv.getModelMap().put("tenderPriceApproval", technicalTenderPriceApproval);
        mv.getModelMap().put("tenderPriceApprovalUser", technicalTenderPriceApprovalUser);
        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.setViewName("forward:tenderMaster.htm?act=techBidOpenView&id=" + id);
        return mv;
    }

