    public ModelAndView receiveBidListBuyer(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        HttpSession session = request.getSession(false);
        if (session != null) {

            String successMessage = (String) session.getAttribute("successMessage");
            if (successMessage != null) {
                mv.addObject("successMessage", successMessage);
                session.removeAttribute("successMessage");
            }

            String failureMessage = (String) session.getAttribute("failureMessage");
            if (failureMessage != null) {
                mv.addObject("failureMessage", failureMessage);
                session.removeAttribute("failureMessage");
            }
        }
        mv.setViewName("Tender/ReceiveBidListBuyerSide");
        return mv;
    }

    public ModelAndView receiveBidListBuyerAjax(HttpServletRequest request, HttpServletResponse response) throws Exception {

        HttpSession session = request.getSession(false);
        UserMaster user = (UserMaster) session.getAttribute("user");
        String userName = user.getLoginName();

        int draw = Integer.parseInt(request.getParameter("draw"));
        int start = Integer.parseInt(request.getParameter("start"));
        int length = Integer.parseInt(request.getParameter("length"));

        String searchValue = request.getParameter("search[value]");

        String orderColumnIndex = request.getParameter("order[0][column]");
        String orderDir = request.getParameter("order[0][dir]");

        if (orderDir == null || orderDir.equals("")) {
            orderDir = "desc";
        }

        if (orderColumnIndex == null || orderColumnIndex.equals("")) {
            orderColumnIndex = "1";
        }

        String orderColumn = "id";

        switch (orderColumnIndex) {

            case "0":
                orderColumn = "id";
                break;

            case "1":
                orderColumn = "refNo";
                break;

            case "2":
                orderColumn = "title";
                break;

            case "3":
                orderColumn = "announceDate";
                break;

            case "4":
                orderColumn = "tender_due_date";
                break;

            case "5":
                orderColumn = "created_by";
                break;

            case "6":
                orderColumn = "tenderPhase";
                break;

            default:
                orderColumn = "id";
                break;
        }

        List list = tenderMasterService.getReceiveBidBuyerPagination(start, length, userName, searchValue, orderColumn, orderDir);
        int totalRecords = tenderMasterService.getReceiveBidBuyerCount(userName);
        int filteredRecords = tenderMasterService.getFilteredReceiveBidBuyerCount(searchValue, userName);

        JSONArray data = new JSONArray();
        int srNo = start + 1;

        for (Object obj : list) {
            TenderMaster tm = (TenderMaster) obj;
            JSONObject row = new JSONObject();

            String refNo = tm.getRefNo();
            int tenderPhase = tm.getTenderPhase();

            String tenderDueDate = tm.getSubmitLastdate();
            String bidStatus = "0";

            String preBidOpenFlag = "0";
            String preBidApproveFlag = "0";

            String techBidOpenFlag = "0";
            String techBidApproveFlag = "0";

            String priceBidOpenFlag = "0";

            SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
            SimpleDateFormat sdf1 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");
            SimpleDateFormat sdf2 = new SimpleDateFormat("dd-MM-yyyy HH:mm:ss");

            Date currentDate = sdf2.parse(sdf2.format(new Date()));

            try {
                if (tenderDueDate != null && !tenderDueDate.trim().equals("")) {
                    Date sysdate1 = sdf.parse(tenderDueDate);
                    String sysdate = sdf1.format(sysdate1);
                    Date submitdate = sdf1.parse(sysdate);

                    Date sysdate12 = sdf.parse(tenderDueDate);
                    String sysdate122 = sdf2.format(sysdate12);
                    Date submitdate2 = sdf2.parse(sysdate122);

                    if (submitdate2.before(currentDate)) {
                        bidStatus = "1";
                    }
                }
            } catch (Exception e) {
                try {
                    Date dueDate = sdf.parse(tenderDueDate);
                    if (dueDate.before(currentDate)) {
                        bidStatus = "1";
                    }
                } catch (Exception ex) {
                    ex.printStackTrace();
                }
            }

            int vendorTotal = 0;
            List vendorList = tenderVendorService.vendorList(refNo);
            if (vendorList != null) {
                vendorTotal = vendorList.size();
            }

            int totalBid = 0;
            List bidList = vendorTenderBidService.vendorList(refNo);
            if (bidList != null) {
                for (Object o : bidList) {
                    totalBid++;
                    try {
                        VendorTenderBid vtb = (VendorTenderBid) o;
                        String bidOpen = vtb.getBidOpenFlag();
                        if ("1".equals(bidOpen)) {
                            priceBidOpenFlag = "1";
                        }

                        String reviseDate = vtb.getReviseDateTime();
                        if (reviseDate != null && !reviseDate.trim().equals("")) {
                            tenderDueDate = reviseDate;
                            Date revisedDate = sdf.parse(reviseDate);
                            bidStatus = "0";
                            if (revisedDate.before(currentDate)) {
                                bidStatus = "1";
                            }
                        }
                    } catch (Exception ex) {
                        ex.printStackTrace();
                    }
                }
            }

            if (tenderPhase == 2) {
                if (tm.getTechBidOpenFlag() == 0) {
                    List techVendorList = vendorTenderBidService.vendorTechBidList(refNo);
                    if (techVendorList != null) {
                        totalBid += techVendorList.size();
                    }
                }
            }

            int totalRegret = 0;
            List regretList = tenderRegretService.regretList(refNo);
            if (regretList != null) {
                totalRegret = regretList.size();
            }

            if (tenderPhase == 3) {
                List preBidList = vendorPreBidService.vendorList(refNo);
                if (preBidList != null) {
                    for (Object o : preBidList) {
                        try {
                            VendorPreBid vpb = (VendorPreBid) o;
                            if ("1".equals(vpb.getBidOpenFlag())) {
                                preBidOpenFlag = "1";
                            }
                            if ("1".equals(vpb.getBidApproveFlag())) {
                                preBidApproveFlag = "1";
                            }
                        } catch (Exception ex) {
                            ex.printStackTrace();
                        }
                    }
                }
            }

            if (tenderPhase == 2 || tenderPhase == 3) {
                List techBidList = vendorTechnicalBidService.vendorList(refNo);
                if (techBidList != null) {
                    for (Object o : techBidList) {
                        try {
                            VendorTechnicalBid vtb = (VendorTechnicalBid) o;
                            if ("1".equals(vtb.getBidOpenFlag())) {
                                techBidOpenFlag = "1";
                            }
                            if ("1".equals(vtb.getBidApproveFlag())) {
                                techBidApproveFlag = "1";
                            }
                        } catch (Exception ex) {
                            ex.printStackTrace();
                        }
                    }
                }
            }

            String vendorTotalHtml = "<a href='javascript:void(0);' onclick=\"loadBitSentVendor('" + refNo + "')\">" + vendorTotal + "</a>";
            String bidReceivedHtml = "<a href='javascript:void(0);' onclick=\"loadBidRRVendor('" + refNo + "')\">" + totalBid + "/" + totalRegret + "</a>";

            StringBuilder bidStatusHtml = new StringBuilder();
            if ("1".equals(bidStatus)) {
                if (tenderPhase == 3 || tenderPhase == 2) {
                    if (tenderPhase == 3 && "1".equals(preBidApproveFlag) && "0".equals(techBidOpenFlag)) {
                        bidStatusHtml.append("<a href='tenderMaster.htm?act=techBidOpenView&id=" + tm.getId() + "'>Tech. bid yet to be open <br><br></a>");
                    }
                    if (tenderPhase == 2 && "0".equals(techBidOpenFlag)) {
                        bidStatusHtml.append("<a href='tenderMaster.htm?act=techBidOpenView&id=" + tm.getId() + "'>Tech. bid yet to be open <br><br></a>");
                    }
                    if ("1".equals(techBidOpenFlag)) {
                        bidStatusHtml.append("<a href='tenderMaster.htm?act=technicalBidApprove&id=" + tm.getId() + "'>Tech. bid open <br><br></a>");
                    }
                }

                if (tenderPhase == 1 && "0".equals(priceBidOpenFlag)) {
                    bidStatusHtml.append("<a href='tenderMaster.htm?act=priceBidOpenView&id=" + tm.getId() + "'>bid yet to be open <br><br></a>");
                }
                if (tenderPhase == 3 || tenderPhase == 2) {
                    if ("1".equals(techBidApproveFlag)) {
                        bidStatusHtml.append("<a href='tenderMaster.htm?act=priceBidOpenView&id=" + tm.getId() + "'>bid yet to be open <br><br></a>");
                    }
                }
            }

            row.put("srNo", srNo++);
            row.put("refNo", refNo);
            row.put("title", tm.getTitle());
            row.put("tenderDate", tm.getAnnounceDate());
            row.put("tenderDueDate", tenderDueDate);
            row.put("createdBy", tm.getContactPerson());
            row.put("tenderPhase", tenderPhase + " Part");
            row.put("vendorTotal", vendorTotalHtml);
            row.put("bidReceived", bidReceivedHtml);
            row.put("bidStatus", bidStatusHtml.toString());

            data.put(row);
        }

        JSONObject result = new JSONObject();
        result.put("draw", draw);
        result.put("recordsTotal", totalRecords);
        result.put("recordsFiltered", filteredRecords);
        result.put("data", data);

        response.setContentType("application/json");
        response.getWriter().write(result.toString());

        return null;
    }

