    public ModelAndView searchVendorToAddInTender(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();

        TenderMaster tenderMaster = new TenderMaster();

        String tenderPhase = request.getParameter("tenderPhase");
        String tender_no = request.getParameter("tender_no");
        String ref_no = request.getParameter("ref_no");

        List<GroupMaster> groupMasterList = (List<GroupMaster>) groupMasterService.read();
        List<GroupCategory> groupCategoryList = (List<GroupCategory>) groupCategoryService.read();
        List<GroupSubCategory> groupSubCategoryList = (List<GroupSubCategory>) groupSubCategoryService.read();

        Map<String, Map<String, List<String>>> groupData = new LinkedHashMap<>();
        for (GroupMaster group : groupMasterList) {
            String groupName = group.getGroupName();
            Map<String, List<String>> categoryMap = groupData.computeIfAbsent(groupName, k -> new LinkedHashMap<>());
            for (GroupCategory category : groupCategoryList) {
                if (category.getGroupMasterId() == group.getId()) {
                    String categoryName = category.getGroupCatogryName();
                    List<String> subCategoryList = categoryMap.computeIfAbsent(categoryName, k -> new ArrayList<>());
                    for (GroupSubCategory sub : groupSubCategoryList) {
                        if (sub.getGroupCategoryId() == category.getId()) {
                            subCategoryList.add(sub.getSubCategoryName());
                        }
                    }
                }
            }
        }
        Gson gson = new Gson();
        mv.addObject("groupHierarchyJson", gson.toJson(groupData));

        List tenderVendor1 = tenderVendorService.readByRfqNo(ref_no);

        mv.addObject("tenderVendor1", tenderVendor1);
        mv.addObject("tenderMaster", tenderMaster);
        mv.addObject("tenderPhase", tenderPhase);
        mv.addObject("ref_no", ref_no);

        mv.setViewName("Tender/AjaxSearchVendorToAddInTender");
        return mv;
    }

    public ModelAndView addVendorForTender(HttpServletRequest request, HttpServletResponse response) throws Exception {
        ModelAndView mv = new ModelAndView();
        TenderMaster tenderMaster = new TenderMaster();
        String tenderPhase = request.getParameter("tenderPhase");
        String tender_no = request.getParameter("tender_no");
        String ref_no = request.getParameter("ref_no");
        String pr_no = request.getParameter("pr_no");
        String vendor_code = "";
        String vendor_name = "";
        String email_id = "";
        String cc = "";
        String mobile_no = "";
        String address = "";
        //checkedId
        try {
            String[] checkId = request.getParameterValues("checkedId");
            for (String checkedValues : checkId) {

                VendorMaster vendorMaster = vendorMasterService.read(checkedValues);
                vendor_code = vendorMaster.getVendorRegNo();
                vendor_name = vendorMaster.getVendorName();

                email_id = vendorMaster.getVendorEmailID();
                cc = vendorMaster.getVendorcc();

                mobile_no = vendorMaster.getVendorMobNo();
                address = vendorMaster.getVendorAddressLine1();

                List tenderVendor1 = tenderVendorService.readByRfqVendor(ref_no, vendor_code);

                if (tenderVendor1.isEmpty()) {
                    TenderVendor tenderVendor = new TenderVendor();
                    tenderVendor.setRfqNo(ref_no);
                    tenderVendor.setRefNo(pr_no);
                    tenderVendor.setVendorCode(vendor_code);
                    tenderVendor.setVendorName(vendor_name);
                    tenderVendor.setAddress(address);
                    tenderVendor.setEmailId(email_id);
                    tenderVendor.setMobileNo(mobile_no);
                    tenderVendor.setChecked(1);
                    tenderVendorService.create(tenderVendor);
                } else {
                    request.setAttribute("failureMessage", "Information: Vendor already added");
                }

            }
        } catch (Exception e11) {
        }
        List tenderVendor1 = prVendorService.readByRfqNo(ref_no);

        //    List list = employeeMasterService.readByDrow();
        //    request.setAttribute("list", list);
        mv.getModelMap().put("tenderVendor1", tenderVendor1);
        mv.getModelMap().put("tenderMaster", tenderMaster);
        mv.getModelMap().put("tenderPhase", tenderPhase);
        mv.getModelMap().put("ref_no", ref_no);
        mv.setViewName("Tender/AjaxSearchVendorToAddInTender1");
        return mv;
    }

